insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('waeu-ma-grod-so-jung-beinaund-sitzn-lossds-uns-de-glaasaln-heebm-und-aufs-leebm-trinkn', 'Wäu ma grod so jung beinaund sitzn - lossds uns de Glaasaln heebm und aufs Leebm trinkn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Weil wir grad so jung beinand sitzen - lasst uns die Glaserln heben und aufs Leben trinken!', '[{"kategorie": "wörtlich", "text": "\"Jetzt, wo wir so jung und gut gelaunt beisammensitzen – lasst uns die Gläser heben und aufs Leben anstoßen!\"  2. Jetzt, wo wir in so jugendlicher Runde vereint sind - lasst uns anstoßen und darauf trinken, was noch kommt!  3. Jetzt, wo wir alle so jung beisammen sitzen - hoch die Gläser auf uns, aufs Leben und auf alles, was zischt!!"}]'::jsonb, ''),
  ('waeu-ma-grod-so-jung-beinaunda-sitzn-woi-mas-heit-so-richtig-krochn-lossn', 'Wäu ma grod so jung beinaunda sitzn, woi mas heit so richtig krochn lossn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Weil wir grad so jung beinander sitzen, woll''n wir''s heut so richtig krachen lassen!', '[{"kategorie": "wörtlich", "text": "\"Jetzt, wo wir so jung und gut gelaunt beisammensitzen, hau''n wir mal so richtig auf den Putz!\"  2. Jetzt, wo wir in so jugendlicher Runde vereint sind, lassen wir mal so richtig die Puppen tanzen!  3. Jetzt, wo wir alle so jung beisammen sitzen, wollen wir feiern, solange der Zapfhahn noch glüht!"}]'::jsonb, ''),
  ('waeu-ma-grod-so-jung-beianaund-sitzn-schdess-ma-au-auf-gestan-heit-und-ollas-wos-uns-jung-hoid', 'Wäu ma grod so jung beianaund sitzn, schdess ma au - auf gestan, heit und ollas, wos uns jung hoid!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Weil wir grad so jung beieinander sitzen, stoßen wir an – auf gestern, heute und alles, was uns jung hält!', '[{"kategorie": "wörtlich", "text": "\"Jetzt, wo wir so jung und gut gelaunt beisammensitzen, wollen wir anstoßen – auf gestern, heute und alles, was uns jung hält!\"  2. Jetzt, wo wir in so jugendlicher Runde vereint sind, lasst uns anstoßen – auf alles, was war, was ist und was uns jung hält!  3. Jetzt, wo wir alle so jung beisammen sitzen, lasst uns trinken auf die Zeit, die uns trägt, und die Freude, die uns jung hält!"}]'::jsonb, ''),
  ('waeu-ma-grod-so-jung-beianaunda-sitzn-lossds-uns-de-glaasaln-heebm-und-aufs-leebm-trinkn', 'Wäu ma grod so jung beianaunda sitzn, lossds uns de Glaasaln heebm und aufs Leebm trinkn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Weil wir grad so jung beieinander sitzen - lasst uns die Glaserln heben und aufs Leben trinken!', '[{"kategorie": "wörtlich", "text": "\"Jetzt, wo wir so jung und gut gelaunt beisammensitzen – lasst uns die Gläser heben und aufs Leben anstoßen!\"  2. Jetzt, wo wir in so jugendlicher Runde vereint sind - lasst uns anstoßen und darauf trinken, was noch kommt!  3. Jetzt, wo wir alle so jung beisammen sitzen - hoch die Gläser auf uns, aufs Leben und auf alles, was zischt!!"}]'::jsonb, ''),
  ('faesch-beinaund', 'fäsch beinaund', '', '', '', 'Wiener Sprüche, die sitzen!', 'fesch beinand!', '[{"kategorie": "wörtlich", "text": "\"schick angezogen\""}, {"kategorie": "", "text": "fein herausgeputzt"}, {"kategorie": "", "text": "top gestylt"}, {"kategorie": "ironisch, negativ konnotiert", "text": "mitgenommen, abgekämpft, lädiert, gebeutelt, gerädert, verkatert"}]'::jsonb, 'Na dea is heid fäsch beinaund!'),
  ('na-dea-is-heid-faesch-beinaund', 'Na dea is heid fäsch beinaund!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Na der sieht heute fesch aus!', '[{"kategorie": "wörtlich", "text": "\"Na der sieht heute fein herausgeputzt aus!\"  2. Der ist heut aber schick angezogen!  3. (ironisch, negativ konnotiert): \"Na, der sieht heute aber mitgenommen aus!\"  4. Na, der schaut heute aber lädiert aus!  5. Mann, sieht der heute gerädert aus!  6. Na, der sieht heut aber echt verkatert aus!"}]'::jsonb, 'fäsch beinaund'),
  ('faesch-beinaund-im-diandlgwaund', 'Fäsch beinaund im Diandlgwaund!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Fesch beinand im Dirndlgewand!', '[{"kategorie": "wörtlich", "text": "\"Top gestylt im Dirndlgewand!\"  2. Fein herausgeputzt im feschen Dirndl!  3. Strahlend schön im Trachtenkleid!"}]'::jsonb, 'fäsch beinaund'),
  ('dea-is-im-kopf-ned-recht-beinaund', 'Dea is im Kopf ned recht beinaund!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der ist im Kopf nicht recht beinand!', '[{"kategorie": "wörtlich", "text": "\"Der hat seine sieben Sinne nicht recht beisammen!\"  2. Der ist nicht ganz bei Sinnen!  3. Der hat nicht alle Tassen im Schrank!"}]'::jsonb, ''),
  ('seids-ned-gaunz-beinaund', 'Seids ned gaunz beinaund?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Seid ihr nicht ganz beinand?', '[{"kategorie": "wörtlich", "text": "\"Seid ihr nicht ganz bei Sinnen?\"  2. Habt ihr den Verstand verloren?  3. Seid ihr noch ganz bei Trost?"}]'::jsonb, ''),
  ('i-bin-min-moong-waeaech-beinaund', 'I bin min Moong wääch beinaund!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Ich bin mit dem Magen weh beinand!', '[{"kategorie": "wörtlich", "text": "\"Ich hab''s mit dem Magen!\"  2. Mein Magen macht Faxen!  3. Ich habe Magenschmerzen!  4. Mir tuts vom Magen her weh!"}]'::jsonb, 'wääch beinaund'),
  ('aum-aumt-wiast-befleegld-schdott-bediint', 'Aum Aumt wiast befleegld schdott bediint!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Am Amt wirst du beflegelt statt bedient!', '[{"kategorie": "wörtlich", "text": "\"Am Amt kriegst du eher einen Anschiss als Hilfe!\"  2. Im Amt gibt’s keine Auskünfte – nur Anschnauzer!  3. Am Amt wird erstmal gebellt, bevor sie dich fragen, was du willst!"}]'::jsonb, ''),
  ('warum-beaugopfln-si-mi-so-penetrant', 'Warum beaugopfln Si mi so penetrant?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Warum beaugapfeln Sie mich so penetrant?', '[{"kategorie": "wörtlich", "text": "\"Warum beäugen Sie mich so penetrant?\"  2. Warum mustern Sie mich so eindringlich?  3. Darf ich fragen, warum Sie mich so intensiv fixieren?"}]'::jsonb, ''),
  ('warum-beeigln-si-mi-so-penetrant', 'Warum beeigln Si mi so penetrant?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Warum beäugeln Sie mich so penetrant?', '[{"kategorie": "wörtlich", "text": "\"Warum beäugen Sie mich so penetrant?\"  2. Warum mustern Sie mich so eindringlich?  3. Darf ich fragen, warum Sie mich so intensiv fixieren?"}]'::jsonb, ''),
  ('ac-dc-schdeed-fia-beidlrock', 'AC/DC schdeed fia Beidlrock!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'AC/DC steht für Beidlrock!', '[{"kategorie": "wörtlich", "text": "\"AC/DC steht für Pimmelrock!\"  2. AC/DC - das ist Testosteron-getränkte Rockmusik!  3. \"AC/DC steht für maskulin geprägten Hardrock!\""}]'::jsonb, ''),
  ('bei-n', 'bei''n', '', '', '', 'Grundwortschatz Wienerisch', 'beim', '[{"kategorie": "wörtlich, Präposition", "text": "\"bei dem\" (vom mittelhochdeutschen \"bî\"=\"bei\")"}]'::jsonb, 'Ea kaufd in Lewakaas bei''n Ihaha!'),
  ('ea-kaufd-in-lewakaas-bei-n-ihaha', 'Ea kaufd in Lewakaas bei''n Ihaha!', '', '', '', 'Wiener Fleischhauer-Slang', 'Er kauft den Leberkäse beim Ihaha!', '[{"kategorie": "wörtlich", "text": "\"Er kauft den Leberkäse beim Pferdefleischhauer\""}, {"kategorie": "", "text": "Er kauft den Leberkäse beim Pferdemetzger!  3. Er kauft den Leberkäse beim Rossfleischer!\""}]'::jsonb, ''),
  ('de-tia-is-baafest-zua', 'De Tia is baafest zua!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Türe ist beinfest zu!', '[{"kategorie": "wörtlich", "text": "\"Die Türe ist bombenfest zu!\"  2. Die Tür ist felsenfest verriegelt!  3. Die Tür ist verrammelt und verriegelt!"}]'::jsonb, ''),
  ('waunns-man-bauschboara-auszoin-schmeiss-i-a-rundn', 'Waunns man Bauschboara auszoin, schmeiss I a Rundn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wenn sie mir den Bausparer auszahlen, schmeiße ich eine Runde!', '[{"kategorie": "wörtlich", "text": "\"Wenn sie mir den Bausparvertrag auszahlen, schmeiße ich eine Runde!\"  2. Sobald das Geld vom Bausparvertrag kommt, geb’ ich einen aus!  3. Ist der Bausparvertrag geplündert, spendier’ ich die nächste Lokalrunde!"}]'::jsonb, ''),
  ('wueuesd-mit-mia-audraan', 'Wüüsd mit mia audraan?', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Willst du mit mir andrehen?', '[{"kategorie": "wörtlich", "text": "\"Willst du dich mit mir anlegen?\"  2. Suchst du Streit mit mir?  3. Willst du dich ernsthaft mit mir anlegen, Freundchen?"}]'::jsonb, ''),
  ('si-auduudln', 'si auduudln', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'sich andudeln', '[{"kategorie": "wörtlich", "text": "\"sich einen anzwitschern\" (lautmalerisches Wort, welches das einfache, gleichförmige Tönen oder summende Spielen eines Dudelsacks nachahmt, vom mittelhochdeutschen \"dudelsac\"=\"Dudelsack\")"}, {"kategorie": "allg.", "text": "sich betrinken, sich besaufen, sich einen Rausch antrinken, sich volllaufen lassen, [[sich]] eintrankeln, [[tschechern]], [[schwassn]]"}]'::jsonb, 'si aubechan'),
  ('auduudld-sei', 'auduudld sei', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'angedudelt sein', '[{"kategorie": "wörtlich", "text": "\"angezwitschert sein\" (lautmalerisches Wort, welches das einfache, gleichförmige Tönen oder summende Spielen eines Dudelsacks nachahmt, vom mittelhochdeutschen \"dudelsac\"=\"Dudelsack\")"}, {"kategorie": "allg.", "text": "\"einen sitzen haben\", rauschig, beschwipst, betrunken, besoffen, sternhagelvoll sein"}]'::jsonb, 'Waun I auduudld bin, reed I lauta Schaas!'),
  ('waun-i-auduudld-bin-reed-i-lauta-schaas', 'Waun I auduudld bin, reed I lauta Schaas!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn ich angedudelt bin, rede ich lauter Schas!', '[{"kategorie": "wörtlich", "text": "\"Wenn ich angedudelt bin, rede ich nur noch Quatsch!\"  2. Wenn ich angedudelt bin, rede ich wie ein kaputter Papagei!  3. Sobald ich einen sitzen habe, rede ich Stuss ohne Ende!"}]'::jsonb, ''),
  ('i-hob-mi-scho-beim-vuaglueuen-komplett-auduudlt', 'I hob mi scho beim Vuaglüün komplett auduudlt!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich habe mich schon beim Vorglühen komplett angedudelt!', '[{"kategorie": "wörtlich", "text": "\"Ich habe mir schon beim Vorglühen einen Vollrausch angetrunken!\"  2. Ich war schon beim Vorglühen [[fett]] wie eine Haubitze!  3. Ich war schon beim Vorglühen sternhagelvoll!"}]'::jsonb, 'si auduudln'),
  ('wem-ane-fraunsn', 'wem ane fraunsn', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem eine fransen', '[{"kategorie": "", "text": "jemandem eine Ohrfeige verpassen"}, {"kategorie": "", "text": "jemandem eine Watsche geben"}, {"kategorie": "", "text": "jemandem eine [[antauchen]], [[auflegen]], [[umhängen]]"}]'::jsonb, ''),
  ('i-frauns-da-glei-aane', 'I frauns da glei aane!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich franse dir gleich eine!', '[{"kategorie": "", "text": "Ich gebe dir gleich eine Orfeige"}, {"kategorie": "", "text": "Ich pasche dir gleich eine!  3. Gleich setzt''s für dich eine [[Watschen]]!"}]'::jsonb, ''),
  ('da-reeng-poschd-aun-de-scheim', 'Da Reeng poschd aun de Scheim!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Regen pascht an die Scheiben!', '[{"kategorie": "wörtlich", "text": "\"Der Regen klatscht gegen die Scheiben!\"  2. Der Regen trommelt gegen die Fenster!  3. Der Regen schlägt gegen die Scheiben!"}]'::jsonb, ''),
  ('wea-beim-poschn-de-heechste-augnzoi-hod-gwinnt-in-preis', 'Wea beim Poschn de heechste Augnzoi hod, gwinnt in Preis!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wer beim Paschen die höchste Augenzahl hat, gewinnt den Preis!', '[{"kategorie": "wörtlich", "text": "\"Wer beim Würfeln die höchste Augenzahl hat, gewinnt den Preis!\"  2. Wer beim Würfeln die meisten Punkte erzielt, holt sich den Gewinn!  3. Der Würfler mit der höchsten Augenzahl räumt den Preis ab!"}]'::jsonb, ''),
  ('i-posch-da-glei-ane', 'I posch da glei ane!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Ich pasche dir gleich eine!', '[{"kategorie": "wörtlich", "text": "\"Ich gebe dir gleich eine Orfeige!\""}, {"kategorie": "", "text": "Gleich setzt''s für dich eine [[Watschen]]!  3. Ich hau dir gleich eine runter!"}]'::jsonb, ''),
  ('ea-hod-ned-nua-poscht-sondan-a-gwueuedad', 'Ea hod ned nua poscht, sondan a gwüüdad!', '', '', '', 'Wiener Gaunersprache', 'Er hat nicht nur gepascht, sondern auch gewildert!', '[{"kategorie": "wörtlich", "text": "\"Er hat nicht nur geschmuggelt, sondern auch gewildert!\"  2. Er hat nicht nur heimlich Waren verschoben, sondern auch Wilderei betrieben!  3. Er war nicht nur als Schmuggler unterwegs , sondern auch als Wilderer! (siehe [[poschn]])"}]'::jsonb, ''),
  ('jetzt-poschts-glei', 'Jetzt poschts glei!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Jetzt pascht es gleich!', '[{"kategorie": "wörtlich", "text": "\"Jetzt gibt''s gleich eine Ohrfeige! \" 2. Gleich setzt''s gleich eine [[Watschen]]!  3. Jetzt knallt''s gleich!"}]'::jsonb, ''),
  ('poschts-de-haend-zsaumm', 'Poschts de Händ zsaumm!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Pascht die Hände zusammen', '[{"kategorie": "wörtlich", "text": "\"Klatscht die Hände zusammen!\"  2. Klatscht die Hände zum Applaus!  3. Schlagt die Hände zusammen – jetzt wird applaudiert!"}]'::jsonb, ''),
  ('poschts-d-handaln-zsaumm', 'Poschts d''Handaln zsaumm!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Pascht die Händchen zusammen', '[{"kategorie": "wörtlich", "text": "\"Klatscht die Händchen zusammen!\"  2. Klatscht die Händchen zum Applaus!  3. Schlagt die Händchen zusammen – jetzt wird applaudiert!"}]'::jsonb, ''),
  ('ind-haend-poschn', 'ind Händ poschn', '', '', '', 'Wiener Sprüche, die sitzen!', 'in die Hände paschen', '[{"kategorie": "wörtlich", "text": "\"die Hände zusammenklatschen\""}, {"kategorie": "", "text": "Beifall klatschen"}, {"kategorie": "", "text": "in die Hände klatschen"}]'::jsonb, ''),
  ('dea-liagt-dass-poschd', 'Dea liagt, dass poschd!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Der lügt, dass es pascht!', '[{"kategorie": "wörtlich", "text": "\"Der lügt, dass es kracht!\"  2. Der lügt, dass sich die Balken biegen!  3. Der lügt, was das Zeug hält!"}]'::jsonb, ''),
  ('poschn-gee', 'poschn gee', '', '', '', 'Wiener Sprüche, die sitzen!', 'paschen gehen', '[{"kategorie": "wörtlich", "text": "\"klatschen gehen\" (vom jiddischen \"pashen\"=\"sich davonstehlen\")"}, {"kategorie": "allg.", "text": "\"losziehen, um sich zu amüsieren\"; \"ausgehen, um sich zu vergnügen\", [[auf]] Läpschi gee"}]'::jsonb, 'Friara samma jeds Wochnend poschn gaungan!'),
  ('friara-samma-jeds-wochnend-poschn-gaungan', 'Friara samma jeds Wochnend poschn gaungan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Früher sind wir jedes Wochenende paschen gegangen!', '[{"kategorie": "wörtlich", "text": "\"Früher sind wir jedes Wochenende ausgegangen, um uns zu amüsieren!\"  2. Früher sind wir jedes Wochenende losgezogen, um Spaß zu haben!  3. Früher waren wir am Wochenende immer unterwegs, um uns zu vergnügen!"}]'::jsonb, 'poschn gee'),
  ('auzaan-wiara-waaglhund', 'auzaan wiara Waaglhund', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'anzerren wie ein Wagerlhund', '[{"kategorie": "wörtlich", "text": "\"anzerren wie der starke Hund, der den Leiterwagen zieht\""}, {"kategorie": "fig.", "text": "mit Volldampf arbeiten, im Akkord schuften, arbeiten wie ein Berserker"}]'::jsonb, ''),
  ('leeg-zeaschd-in-zund-hi-und-daunn-de-klaanan-astln-sunst-faungds-feia-ned-richtig', 'Leeg zeaschd in Zund hi und daunn de klaanan Astln - sunst faungds Feia ned richtig!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Leg erst den Zund hin und dann die kleinen Äste – sonst fängt das Feuer nicht richtig!', '[{"kategorie": "wörtlich", "text": "\"Zuerst kommt das Anzündmaterial, dann die kleinen Zweige – nur so brennt das Feuer gut an!\"  2. Erst das Anfeuermaterial, dann die kleinen Holzstücke – sonst bekommst du keine Flamme!  3. Ein gutes Feuer entsteht in Schichten: Zunder unten, Zündholz oben!"}]'::jsonb, ''),
  ('ea-is-an-zund-aufgsessn', 'Ea is an Zund aufgsessn!', '', '', '', 'Wiener Gaunersprache', 'Er ist einem Zund aufgesessen!', '[{"kategorie": "wörtlich", "text": "\"Er ist einem Hinweisgeber der Polizei aufgesessen!\"  2. Er ist auf einen Informanten der Polizei hereingefallen!  3. Er hat sich von einem Spitzel der Polizei täuschen lassen!"}]'::jsonb, ''),
  ('ea-troogd-sei-hemad-imma-mid-aufkraempaede-aeamaen', 'Ea troogd sei Hemad imma mid aufkrämpäde Äamän!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er trägt sein Hemd immer mit aufgekrempelten Ärmeln!', '[{"kategorie": "wörtlich", "text": "\"Er trägt sein Hemd immer mithochgekrempelten Ärmeln!\"  2. Er trägt sein Hemd stets mit aufgerollten Ärmeln!  3. Ihn sieht man selten mit langen Hemdsärmeln – die sind immer umgeschlagen!"}]'::jsonb, ''),
  ('da-buanaeamae-woa-guat-duachzoong-und-bsundas-wiazig', 'Da Buanäamä woa guat duachzoong und bsundas wiazig!', '', '', '', 'Wiener Fleischhauer-Slang', 'Der Burenärmel war gut durchgezogen und besonders würzig!', '[{"kategorie": "wörtlich", "text": "\"Der Burenärmel war schön durchgereift und hatte ein intensives Aroma!\"  2. Der [[Burenhaxen]] war gut abgehangen und geschmacklich hervorragend abgestimmt!  3. Die Würze war ausgewogen, der Burenärmel perfekt durchgezogen!"}]'::jsonb, ''),
  ('da-buanhaxn-woa-guat-duachzoong-und-besundas-wiazig', 'Da Buanhaxn woa guat duachzoong und besundas wiazig!', '', '', '', 'Wiener Fleischhauer-Slang', 'Der Burenhaxen war gut durchgezogen und besonders würzig!', '[{"kategorie": "wörtlich", "text": "\"Der Burenhaxen war schön durchgereift und hatte ein intensives Aroma!\"  2. Der [[Burenärmel]] war gut abgehangen und geschmacklich hervorragend abgestimmt!  3. Die Würze war ausgewogen, der Burenhaxen perfekt durchgezogen!"}]'::jsonb, ''),
  ('im-summa-troog-i-imma-nua-a-aafochs-aeamaeleiwal-und-a-kuaze', 'Im Summa troog I imma nua a aafochs Äamäleiwal und a Kuaze!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Im Sommer trag ich immer nur ein einfaches Ärmelleibchen undeine Kurze!', '[{"kategorie": "wörtlich", "text": "\"Im Sommer trag ich immer nur ein einfaches Ärmelleibchen und Shorts!\"  2. Im Sommer trage ich meist nur ein schlichtes T-Shirt und Shorts!  3. Im Sommer ziehe ich meistens ein T-Shirt und eine kurze Hose an!"}]'::jsonb, ''),
  ('dea-hod-an-aeamae-wiara-boxa', 'Dea hod an Äamä wiara Boxa!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der hat einen Ärmel wie ein Boxer', '[{"kategorie": "", "text": "Der hat einen Bizeps wie ein Boxer!  2. Bei dem platzt der Ärmel vor lauter Bizeps!  3. Der hat Oberarme wie ein Schwergewichtsboxer!"}]'::jsonb, ''),
  ('heit-reiss-i-ma-an-hasn-auf', 'Heit reiss I ma an Håsn auf!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Heute reiße ich mir einen Hasen auf!', '[{"kategorie": "", "text": "Heute werde ich ein hübsches Mädchen anbaggern!  2.  Heute werde ich ein hübsches Mädchen abschleppen!  3. Heute wird ein heißer Hase mit mir nach Hause gehen!"}]'::jsonb, ''),
  ('ea-reissd-maadln-auf-wia-buttabroodpapia', 'Ea reissd Maadln auf wia Buttabroodpapia!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Er reißt Madln auf wie Butterbrotpapier!', '[{"kategorie": "wörtlich", "text": "\"Er reißt Mädchen auf wie Butterbrotpapier!\"  2. Wie Butterbrotpapier so fein, wickelt er die Madln ein!  3. Die Mädels fallen bei ihm schneller als Dominosteine im Orkan!"}]'::jsonb, ''),
  ('s-maeu-aufreissn', 's Mäu aufreissn', '', '', '', 'Wiener Sprüche, die sitzen!', 'das Maul aufreißen', '[{"kategorie": "wörtlich", "text": "\"den Mund weit aufreißen\""}, {"kategorie": "", "text": "den Mund vollnehmen"}, {"kategorie": "", "text": "den Mund \"aushängen\" (gähnen)"}]'::jsonb, ''),
  ('da-auschdich-krochd-und-s-bia-eawochd', 'Da Auschdich krochd, und s''Bia eawochd!', '', '', '', 'Echte Wiener Schmähperlen', 'Der Anstich kracht, und das Bier erwacht!', '[{"kategorie": "wörtlich", "text": "Anstich, Plopp - und der Zapfen ist ab!  2. Erst der Anstich, dann der Tausch – Bier gegen Bauch!  3. Ein Schlag, ein Schrei, ein See – der Anstich ist passé!"}]'::jsonb, ''),
  ('i-hob-ma-an-rausch-auzichd-dea-schnoella-gwochsn-is-ois-a-bambus', 'I hob ma an Rausch auzichd, dea schnölla gwochsn is ois a Bambus!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ich habe mir einen Rausch angezüchtet, der schneller gewachsen ist als ein Bambus!', '[{"kategorie": "wörtlich", "text": "\"Ich habe mir einen Rausch angezüchtet, hätte aber nie gedacht, dass dieser schneller wächst als Bambus!\"  2. Ich hab einen Rausch gepflanzt und eine Alkoholplantage geerntet!  3. Geplant war ein netter Pegel – geworden ist daraus ein Tauchgang!"}]'::jsonb, ''),
  ('dea-is-so-ausgfuxd-dassa-in-reiwa-den-fuxmurra-wiida-zruckgflaadat-hood', 'Dea is so ausgfuxd, dassa in Reiwa den Fuxmurra wiida zruckgflaadat hood!', '', '', '', 'Wiener Gaunersprache', 'Der ist so ausgefuchst, dass er dem Räuber den Fuchsmurrer wieder zurückgefladert hat!', '[{"kategorie": "wörtlich, Gaunersprache", "text": "\"Der ist so ausgefuchst, dass er dem Räuber den erbeuteten Schmuck wieder zurückgestohlen hat!\"  2. Der ist so gerissen, dass er dem Dieb den Goldschmuck wieder abgeknöpft hat!  3. Der ist so erfahren und trickreich, dass er dem Räuber seine Beute wieder aus der Tasche gezogen hat!"}]'::jsonb, ''),
  ('waunn-de-augschitt-is-wiads-zua-kuschlrakeedn', 'Waunn de augschitt is, wiads zua Kuschlrakeedn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Wenn die angeschüttet ist, wird sie zur Kuschelrakete!', '[{"kategorie": "wörtlich", "text": "\"Wenn die einen hinter der Binde hat, wird sie zur Kuschelrakete!\"  2. Sobald sie leicht einen sitzen hat, wird sie plötzlich anhänglich und schmusig!  3. Wenn sie leicht beschwipst ist, verwandelt sich plötzlich in einen Schmuseautomaten!"}]'::jsonb, ''),
  ('bist-augschitt', 'Bist augschitt?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Bist du angeschüttet?', '[{"kategorie": "wörtlich", "text": "\"Bist du noch ganz dicht?\"  2. Hast du sie noch alle?  3. Bist du total gestört?  4. [[Bist]] ballaballa?"}]'::jsonb, ''),
  ('bist-ballaballa', 'Bist ballaballa?', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Bist ballaballa?', '[{"kategorie": "wörtlich", "text": "\"Bist du ballaballa?\"  2. Bist du noch ganz dicht?\"  3. Hast du sie noch alle?  4. Bist du total gestört?  4. [[Bist]] augschitt?"}]'::jsonb, ''),
  ('heast-augschitta-bist-waach-in-da-bian', 'Heast, Augschitta, bist waach in da Bian?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hey, Angeschütteter, bist du weich in der Birne?', '[{"kategorie": "wörtlich", "text": "\"Sag mal, du Angeschütteter, bist du weich in der Birne?\"  2. Sag mal, Angesäuselter, bist du nicht ganz dicht?  3. Hör mal, Suffkopf, hast du einen an der Waffel?"}]'::jsonb, ''),
  ('heast-augschdraada-bist-waach-in-da-bian', 'Heast, Augschdraada, bist waach in da Bian?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hey, Angestreuter, bist du weich in der Birne?', '[{"kategorie": "wörtlich", "text": "\"Sag mal, du Angeschütteter, bist du weich in der Birne?\"  2. Sag mal, Angesäuselter, bist du nicht ganz dicht?  3. Hör mal, Suffkopf, hast du einen an der Waffel?"}]'::jsonb, ''),
  ('aufm-aumt-hackln-lauta-augschitte', 'Aufm Aumt hackln lauta Augschitte!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Auf diesem Amt arbeiten lauter Angeschüttete!', '[{"kategorie": "wörtlich", "text": "\"Auf diesem Amt arbeiten lauter Totalgestörte!\"  2. \"Auf diesem Amt arbeiten nur Vollpfosten!\"  3. Auf dem Amt sitzen nur [[Schüttis]]!"}]'::jsonb, ''),
  ('aufm-aumt-hackln-lauta-schuettis', 'Aufm Aumt hackln lauta Schüttis!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Auf diesem Amt arbeiten lauter Schüttis!', '[{"kategorie": "wörtlich", "text": "\"Auf diesem Amt arbeiten lauter Totalgestörte!\"  2. \"Auf diesem Amt arbeiten nur Vollpfosten!\"  3. Auf dem Amt laufen nur [[Angeschüttete]] herum!"}]'::jsonb, ''),
  ('dea-is-komplett-augschitt', 'Dea is komplett augschitt!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der ist komplett angeschüttet!', '[{"kategorie": "wörtlich", "text": "\"Der ist total gestört!\"  2. Der ist total plemplem!  3. Der ist mehr ganz dicht!  4. Der hat sie nicht mehr alle!"}]'::jsonb, ''),
  ('in-da-hektik-is-in-redaktaea-a-antn-duachgrutschd', 'In da Hektik is in Redaktäa a Antn duachgrutschd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'In der Hektik ist dem Redakteur eine Ente durchgerutscht!', '[{"kategorie": "wörtlich", "text": "\"In der Eile hat der Redakteur eine Falschmeldung veröffentlicht!\"  2. Der Redakteur hat im Trubel versehentlich eine Zeitungsente übernommen!  3. Der Redakteur ließ in der Hektik eine ungeprüfte Information durchrutschen!"}]'::jsonb, ''),
  ('dea-woogld-dahea-wiara-antn', 'Dea woogld dahea wiara Antn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Der wackelt daher wie eine Ente!', '[{"kategorie": "wörtlich", "text": "\"Der watschelt durch die Gegend wie ein Entlein!\"  2. Der hat einen Watschelgang wie eine Ente!  3. Der bewegt sich wie ein Entlein auf der Flucht!"}]'::jsonb, ''),
  ('raamds-de-gaunzn-antn-weg-damit-kana-siichd-wuefueue-ma-gsoffn-haum', 'Raamds de gaunzn Antn weg, damit kana siichd, wüfüü ma gsoffn haum!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Räumt die ganzen Enten weg, damit niemand sieht, wie viel wir gesoffen haben!', '[{"kategorie": "wörtlich", "text": "\"Räumt die ganzen Leerflaschen weg, damit niemand sieht, wie viel wir gesoffen haben!\"  2. Räumt die Leergutberge weg, sonst denken die Leute, wir sind Alkoholiker!  3. Lasst die Glasleichen verschwinden, bevor es peinlich wird!"}]'::jsonb, ''),
  ('waradn-olle-lesbn-aus-lesbos-daedns-bei-uns-ned-antn-haassn', 'Waradn olle Lesbn aus Lesbos, dädns bei uns ned ''Antn'' haassn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wären alle Lesben aus Lesbos, würden sie bei uns nicht ''Anten'' heißen!', '[{"kategorie": "wörtlich", "text": "\"Wären alle Lesben aus Lesbos, würden sie bei uns nicht ''Enten'' heißen!\"  2. Wären Lesben nur Lesbierinnen, würden sie bei uns sicher nicht „Enten“ heißen!  3. Hätten alle Lesben ihren Ursprung auf Lesbos, blieben unsere ''Antn'' einfach Enten!"}]'::jsonb, ''),
  ('da-baumpaletsch-hat-so-scheene-schneckaln-ois-wia-da-papa-is-owa-blond-wia-de-mama', 'Da Baumpaletsch hat so scheene Schneckaln ois wia da Papa, is owa blond wia de Mama!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Bamperletsch hat so schöne Schneckerln wie der Papa, ist aber blond wie die Mama!', '[{"kategorie": "wörtlich", "text": "\"Das Kindchen hat so schöne Locken wie der Papa, ist aber blond wie die Mama!\"  2. Das Kind hat Papas Locken, aber Mamas blonde Haare!  3. Die Locken vom Bamperletsch kommen ganz nach dem Papa, die Haarfarbe aber eindeutig von der Mama!"}]'::jsonb, ''),
  ('si-woa-ois-kind-a-richtiga-baumpaletsch-rund-gsund-und-imma-hungrig', 'Si woa ois Kind a richtiga Baumpaletsch - rund, gsund und imma hungrig!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sie war als Kind ein richtiger Bamperletsch – rund, gesund und immer hungrig!', '[{"kategorie": "wörtlich", "text": "\"Sie war als Kind ein richtiges Pummelchen – rund, gesund und immer hungrig!\"  2. Als Kind hatte sie ordentlich Babyspeck um die Hüften und immer einen gesunden Appetit!   3. Als Kind war sie ein kleines, süßes Speckbäckchen mit Dauerhunger und großem Herzen!"}]'::jsonb, ''),
  ('de-gaunze-bagaasch-kaunn-ma-gschdoin-bleibm', 'De gaunze Bagaasch kaunn ma gschdoin bleibm!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die ganze Bagage kann mir gestohlen bleiben!', '[{"kategorie": "wörtlich", "text": "\"Die ganze Sippschaft kann mir gestohlen bleiben!\"  2. Auf die ganze Bande kann ich verzichten!\"  3. Mit diesem Pack will ich nichts zu tun haben!"}]'::jsonb, ''),
  ('wos-wueue-denn-de-gaunze-bagaasch-do-de-soin-si-schleichn', 'Wos wüü denn de gaunze Bagaasch do? De soin si schleichn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Was will denn die ganze Bagage hier? Die sollen sich schleichen!', '[{"kategorie": "wörtlich", "text": "\"Was will denn dieses Gesindel hier? Die sollen verschwinden!\"  2. Was hat dieses Pack hier zu suchen? Die sollen abhauen!  3. Was will denn dieses Lumpenpack da? Die sollen sich [[verzupfen]]!"}]'::jsonb, ''),
  ('so-a-muadsbagaasch-des-san-jo-kaane-menschn', 'So a Muadsbagaasch - des san jo kaane Menschn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'So eine Mordsbagage, des sind doch keine Menschen!', '[{"kategorie": "wörtlich", "text": "\"Was für ein mordsmäßiges Gesindel - das sind doch keine zivilisierten Menschen!\"  2. So ein mieses Pack – das sind Tiere, keine Leute!  3. Was für eine Mordsbagage - das ist der Abschaum der Menschheit!"}]'::jsonb, ''),
  ('de-goeoedgeile-muadsbagaasch-von-meine-schwiigaleit-tauchd-imma-genau-daunn-auf-waunns-ums-eabn-geed', 'De göödgeile Muadsbagaasch von meine Schwiigaleit tauchd imma genau daunn auf, waunns ums Eabn geed!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Die geldgeile Mordsbagage meiner Schwiegerleute taucht immer genau dann auf, wenn’s ums Erben geht!', '[{"kategorie": "wörtlich", "text": "\"Das geldgeile Mordspack meiner Schwiegerbrut taucht immer genau dann auf, wenn’s ums Erben geht!\"  2. Sobald’s ums Erben geht, steht die ganze mordsgierige Verwandtschaftsmeute meiner Schwiegerfamilie auf der Matte!  3. Kaum ist von Erbe die Rede, schwärmt das mordsgierige Aasgeiergeschwader der Schwiegerseite aus!"}]'::jsonb, ''),
  ('a-echta-baraawara-hackld-tog-und-nocht-und-jaummad-nii', 'A echta Baraawara hackld Tog und Nocht und jaummad nii!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ein echter Baraberer hackelt Tag und Nacht und jammert nie!', '[{"kategorie": "wörtlich", "text": "\"Ein echter Schwerarbeiter arbeitet Tag und Nacht und jammert nie!\"  2. Ein wahrer Baraberer schuftet rund um die Uhr und klagt kein einziges Mal!  3. Ein Schwerarbeiter kennt keinen Feierabend und kein Jammern!"}]'::jsonb, ''),
  ('jetzt-samma-bare', 'Jetzt samma bare!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Jetzt sind wir pari!', '[{"kategorie": "wörtlich", "text": "\"Jetzt sind wir pari!\"  2. Jetzt sind wir quitt!  3. Jetzt sind wir wieder im Reinen miteinander!"}]'::jsonb, ''),
  ('mei-bauchal-is-ka-foeoela-do-host-gscheid-wos-zum-schdreichln', 'Mei Bauchal is ka Fööla - do host gscheid wos zum Schdreichln!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Mein Baucherl ist kein Fehler - da hast du g''scheit was zu streicheln!', '[{"kategorie": "wörtlich", "text": "\"Mein Baucherl ist kein Fehler - freu dich auf viel Fläche zum Streicheln!\"  2. Mein Bäuchlein ist ein riesiger Kuschelplatz – weich, süchtig machend und immer für dich da!  3. Das ist kein Bäuchlein, das ist ein Liebesberg - besteige mich!"}]'::jsonb, ''),
  ('gee-ooba-gib-uns-no-zwa-bauchaln', 'Gee, Ooba, gib uns no zwa Bauchaln!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Geh, Ober, gib uns noch zwei Baucherln!', '[{"kategorie": "wörtlich", "text": "\"Bitte, Kellner, geben Sie uns noch zwei Cola-Weinbrand!\"  2. Bitte noch zweimal Weinbrand auf Cola, Herr Ober!  3. Herr Ober, bitte noch zwei Baucherl nachlegen!"}]'::jsonb, ''),
  ('dea-beachad-ned-schlecht', 'Dea beachad ned schlecht!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der bechert nicht schlecht!', '[{"kategorie": "wörtlich", "text": "Der weiß, wie man den Becher leert!“  2. Der haut ordentlich einen rein!  3. Der trinkt wie ein Loch!"}]'::jsonb, ''),
  ('a-guada-beifoara-hoid-de-goschn-und-tuad-so-ois-haeda-ka-aungst', 'A guada Beifoara hoid de Goschn und tuad so, ois häda ka Aungst!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ein guter Beifahrer hält die Goschen und tut so, als hätte er keine Angst!', '[{"kategorie": "wörtlich", "text": "\"Ein guter Beifahrer hält die Klappe und tut so, als hätte er keine Angst!\"  2. Ein guter Beifahrer hält die Fresse und leidet stumm!  3. Ein guter Beifahrer sagt kein Wort, sondern betet stumm, dass es nicht kracht!"}]'::jsonb, ''),
  ('i-hob-so-vueue-beifoara-ghobd-dass-i-soeoewa-nimma-foan-kau', 'I hob so vüü Beifoara ghobd, dass I sööwa nimma foan kau!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ich habe so viele Beifahrer gehabt, dass ich selber nicht mehr fahren kann!', '[{"kategorie": "wörtlich", "text": "\"Ich hatte so viele Begleitschnäpse zum Bier, dass ich nicht mehr selbst fahren kann!\"  2. Nach all den Schnapsrunden zum Bier bin ich definitiv nicht mehr fahrtauglich!  3. Ich hab'' so viele Kurze zum Bier gehabt, dass ich mein Auto nur noch anschauen kann!  4. Nach den ganzen Beifang-Schnäpsen zum Bier bleibt nur noch das Taxi!"}]'::jsonb, ''),
  ('in-franzoesisch-weama-jetza-vom-beiwaagal-untarricht', 'In Französisch weama jetza vom Beiwaagal untarricht!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'In Französisch werden wir jetzt vom Beiwagerl unterrichtet!', '[{"kategorie": "wörtlich", "text": "\"In Französisch werden wir jetzt von der Assistenzlehrerin unterrichtet!\"  2. Den Französischunterricht übernimmt bei uns jetzt die Assistenzlehrerin!  3. Unsere Französischstunden werden nun von der Lehrassistentin geleitet!"}]'::jsonb, ''),
  ('des-beiwaagal-is-praktisch-waeu-jetzt-hod-de-biakistn-aa-an-eiganan-sitzplotz', 'Des Beiwaagal is praktisch – wäu jetzt hod de Biakistn aa an eiganan Sitzplotz!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das Beiwägelchen ist praktisch – denn jetzt hat die Bierkiste auch einen eigenen Sitzplatz!', '[{"kategorie": "wörtlich", "text": "\"Der Seitenwagen ist praktisch – denn jetzt hat die Bierkiste auch einen eigenen Sitzplatz!\"  2. Seit ich einen Seitenwagen habe, fährt die Bierkiste standesgemäß mit!  3. Endlich muss ich die Bierkiste nicht mehr auf dem Schoß balancieren – der Seitenwagen machts möglich!"}]'::jsonb, ''),
  ('ma-waass-nii-wos-kummd-desweng-hob-i-neembei-a-beiwaagal-fois-de-hauptfrau-moi-schdreikt', 'Ma waass nii, wos kummd – desweng hob I neembei a Beiwaagal, fois de Hauptfrau moi schdreikt!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Man weiß nie, was kommt – deshalb hab ich nebenbei ein Beiwägelchen, falls die Hauptfrau mal streikt!', '[{"kategorie": "wörtlich", "text": "\"Man weiß nie, was kommt – deshalb hab ich nebenbei einen Ersatzpartner, falls die Hauptfrau mal streikt!\"  2. Falls die Hauptfrau den Dienst verweigert, springt das Beiwagerl ein!  3. Neben der Chefin hab ich noch ein Beiwagerl auf Abruf!"}]'::jsonb, ''),
  ('oone-beiwagal-ist-des-bia-wiara-motorradl-oone-seitnwoong-iagendwia-unvoischdaendig', 'Oone Beiwagal ist des Bia wiara Motorradl oone Seitnwoong – iagendwia unvoischdändig!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ohne Beiwagerl ist das Bier wie ein Motorrad ohne Seitenwagen – irgendwie unvollständig', '[{"kategorie": "wörtlich", "text": "\"Ohne Beiwägelchen ist das Bier wie ein Motorrad ohne Seitenwagen – irgendwie unvollständig!\"  2. Ein Bier ohne Beiwagerl ist wie ein Motorrad ohne Seitenwagen – läuft, aber macht weniger Spaß!  3. Das Bier fährt zwar auch solo, aber erst mit dem Beiwagerl sind wir komplett!"}]'::jsonb, ''),
  ('da-beiwoong-is-praktisch-waeu-jetzt-hod-de-biakistn-aa-an-eiganan-sitzplotz', 'Da Beiwoong is praktisch – wäu jetzt hod de Biakistn aa an eiganan Sitzplotz!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Beiwagen ist praktisch – denn jetzt hat die Bierkiste auch einen eigenen Sitzplatz!', '[{"kategorie": "wörtlich", "text": "\"Der Seitenwagen ist praktisch – denn jetzt hat die Bierkiste auch einen eigenen Sitzplatz!\"  2. Seit ich einen Seitenwagen habe, fährt die Bierkiste standesgemäß mit!  3. Endlich muss ich die Bierkiste nicht mehr auf dem Schoß balancieren – der Seitenwagen machts möglich!"}]'::jsonb, ''),
  ('ma-waass-nii-wos-kummd-desweng-hob-i-zusaetzlich-no-an-beiwoong-fois-de-hauptfrau-moi-schdreikt', 'Ma waass nii, wos kummd – desweng hob I zusätzlich no an Beiwoong, fois de Hauptfrau moi schdreikt!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Man weiß nie, was kommt – deshalb hab ich zusätzlich noch einen Beiwagen, falls die Hauptfrau mal streikt!', '[{"kategorie": "wörtlich", "text": "\"Man weiß nie, was kommt – deshalb hab ich nebenbei einen Ersatzpartner, falls die Hauptfrau mal streikt!\"  2. Falls die Hauptfrau den Dienst verweigert, springt das [[Beiwagerl]] ein!  3. Neben der Chefin hab ich noch ein [[Beiwagerl]] auf Abruf!"}]'::jsonb, ''),
  ('sei-ma-ned-baeaes', 'Sei ma ned bääs!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Sei mir nicht bös!', '[{"kategorie": "wörtlich", "text": "\"Sei mir nicht böse!\"  2. Bitte nimm es mir nicht übel!  3. Sei mir nicht gram!"}]'::jsonb, ''),
  ('i-bin-da-ned-baeaes', 'I bin da ned bääs!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich bin dir nicht bös!', '[{"kategorie": "wörtlich", "text": "\"Ich bin dir nicht böse!\"  2. Ich nehme es dir nicht übel!   3. Ich bin dir nicht gram!"}]'::jsonb, ''),
  ('muang-betonia-ma-des-fundament-fiad-garaasch', 'Muang betonia ma des Fundament fiad Garaasch!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Morgen betonieren wir das Fundament für die Garage!', '[{"kategorie": "wörtlich", "text": "\"Morgen gießen wir das Betonfundament für die Garage!\"  2. Morgen machen wir die Betonplatte für die Garage fertig!  3. Morgen nageln wir das Garagenfundament in den Boden – mit Beton bis zum Anschlag!"}]'::jsonb, ''),
  ('i-betonia-da-glei-ane', 'I betonia da glei ane!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Ich betoniere dir gleich eine!', '[{"kategorie": "wörtlich", "text": "\"Ich haue dir gleich eine runter!\"  2. Ich schlage dir gleich (ins Gesicht)!  2. Ich verpasse dir gleich eine [[Watschen]]!  3. Ich polier dir gleich die Fresse!"}]'::jsonb, ''),
  ('wem-ane-betonian', 'wem ane betonian', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem eine betonieren', '[{"kategorie": "wörtlich", "text": "\"jemandem eine runterhauen\""}, {"kategorie": "", "text": "jemandem einen Faustschlag versetzen"}, {"kategorie": "", "text": "jemandem eine heftige Watschen verpassen"}]'::jsonb, ''),
  ('noch-sein-potza-hod-eam-da-schaeaef-reglrechd-betoniad', 'Noch sein Potza hod eam da Schääf reglrechd betoniad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Nach seinem Patzer hat ihn der Chef regelrecht betoniert!', '[{"kategorie": "wörtlich", "text": "\"Nach seinem Patzer hat ihn der Chef gewaltig zusammengestaucht!\"  2. Nach dem Patzer hat ihn der Chef förmlich in der Luft zerrissen!  3. Nach seinem Patzer hat er vom Chef eine richtige Standpauke kassiert!"}]'::jsonb, ''),
  ('si-zuabetonian', 'si zuabetonian', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'sich zubetonieren', '[{"kategorie": "wörtlich", "text": "\"sich zubetonieren\" (vom französischen \"bétonner\"=\"zubetonieren\")"}, {"kategorie": "scherzhaft für", "text": "[[sich zuschütten]], sich vollaufen lassen, sich einen Vollrausch antrinken, sich bis zur Bewusstlosigkeit besaufen, \"sich die Kante geben\", \"sich abschießen bis zum Filmriss\", [[si]] zuaschwaassn, [[si]] zurealn, [[si]] niidakiiwän"}]'::jsonb, 'si de Guakn geebm'),
  ('si-zuaschiidn', 'si zuaschiidn', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'sich zuschütten', '[{"kategorie": "wörtlich", "text": "\"sich zuschütten\" (vom mittelhochdeutschen \"schütten\"=\"zuschütten\")"}, {"kategorie": "scherzhaft für", "text": "[[sich zubetonieren]], sich vollaufen lassen, sich einen Vollrausch antrinken, sich bis zur Bewusstlosigkeit besaufen, \"sich die Kante geben\", \"sich abschießen bis zum Filmriss\", [[si zuaschwaassn]], [[si niidakiiwän]]"}]'::jsonb, 'Da Plan woara Feiaobndbia - owa zum Schluss hauma uns olle zuagschiid!'),
  ('eigentlich-woid-i-nua-a-bia-trinkn-owa-iatuemlich-hob-i-mi-daunn-zuabetoniad', 'Eigentlich woid I nua a Bia trinkn, owa iatümlich hob I mi daunn zuabetoniad!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Eigentlich wollte ich nur ein Bier trinken, aber irrtümlich habe ich mich dann zubetoniert!', '[{"kategorie": "wörtlich", "text": "\"Eigentlich wollte ich nur ein Bier trinken, aber aus Versehen habe ich mich dann zubetoniert!\"  2. Eigentlich war nur ein Bier geplant – aber am Schluss hatte ich mich komplett zugeschüttet!  3. Ich wollte nur einen Schluck nehmen und hab mich versehentlich in mein eigenes Betonfundament gegossen!"}]'::jsonb, 'si zuabetonian'),
  ('da-plan-woara-feiaobndbia-owa-zum-schluss-hauma-uns-olle-zuagschiid', 'Da Plan woara Feiaobndbia - owa zum Schluss hauma uns olle zuagschiid!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der Plan war ein Feierabendbier - aber zum Schluss haben wir uns alle zugeschüttet!', '[{"kategorie": "wörtlich", "text": "\"Das Feierabendbier ist eskaliert – zum Schluss haben wir uns komplett weggeschüttet!\"  2. Eigentlich wollten wir nur eins trinken – am Ende waren wir aber voll wie eine Tankstelle!  3. Es sollte nur ein Absacker sein, aber daraus wurde ein feuchtfröhlicher Sturzflug!"}]'::jsonb, 'si zuaschiidn'),
  ('bia-is-fluessigs-brood-nua-bessa-gwueazd', 'Bia is flüssigs Brood - nua bessa gwüazd!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Bier ist flüssiges Brot - nur besser gewürzt!', '[{"kategorie": "wörtlich", "text": "\"Bier ist Vollkorn zum Trinken – mit einem würzigen Charakter!\"  2. Bier ist der Smoothie des kleinen Mannes!  3. Bier deckt meinen täglichen Brotkonsum - flüssig!"}]'::jsonb, ''),
  ('i-brauch-kan-sixpack-i-hob-a-biawaumpn-deluex', 'I brauch kan Sixpack - I hob a Biawaumpn Delüx!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ich brauche keinen Sixpack - ich habe eine Bierwampe Deluxe!', '[{"kategorie": "wörtlich", "text": "\"Wozu ein Sixpack, wenn ich ein ganzes Fass habe?\"  2. Mein Waschbrettbauch ist halt weichgespült – nennt sich Bierkomfortzone!  3. Ich brauch keinen Sixpack – ich trag mein Bier außen!  4. Besser eine Wampe mit Bier als ein Bizeps ohne Bier!"}]'::jsonb, ''),
  ('unsa-biabeisl-hod-mea-promueue-ois-quadraadmaeaeta', 'Unsa Biabeisl hod mea Promüü ois Quadraadmääta!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Unser Bierbeisl hat mehr Promille als Quadratmeter!', '[{"kategorie": "wörtlich", "text": "\"Unsere Bierkneipe hat mehr Promille als Quadratmeter!\"  2. In unserem Bierbeisl ist der Alkoholpegel höher als die Mietkosten!  3. Unsere Bierkneipe hat mehr Promille als Sitzplätze!"}]'::jsonb, ''),
  ('a-echta-biatippla-klopfd-aufs-fassl-und-waass-genau-wuevueue-a-no-aussehoin-kaunn', 'A echta Biatippla klopfd aufs Fassl und waass genau, wüvüü a no aussehoin kaunn!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Ein echter Biertippler klopft ans Fass und weiß dann genau, wie viel er noch rausholen kann!', '[{"kategorie": "wörtlich", "text": "\"Ein echter Biertippler braucht klopfen und weiß genau, wie viel noch im Fass ist!\"  2. Ein Biertippler klopft kurz – und weiß genau: Noch drei gute Schlucke drin!  3. Ein echter Biertippler erkennt den Bierfüllstand mit bloßem Ohr!"}]'::jsonb, ''),
  ('restltrinka-haums-zu-eam-gsogd-hoib-bettla-hoib-schdrachoida-a-zecha-oone-zech', 'Restltrinka haums zu eam gsogd, hoib Bettla, hoib Schdrachoida - a Zecha oone Zech!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Restltrinker haben sie zu ihm gesagt, halb Bettelmann, halb Stracholder – ein Zecher ohne Zeche!', '[{"kategorie": "wörtlich", "text": "\"Restltrinker nannte man ihn, halb Bettelmann, halb Landstreicher – ein Zecher ohne Zeche!\"  2. Man nannte ihn den Restltrinker – ein Herumtreiber mit leerem Krug und ohne Obdach!  3. Er galt als Restltrinker, halb Vagabund, halb Lump – stets durstig, nie mit fester Bleibe!"}]'::jsonb, ''),
  ('da-restltrinka-hockd-wiida-beim-wiatn-aum-hintaeingaung-und-hoffd-aufn-letztn-tropfn-ausn-fassl', 'Da Restltrinka hockd wiida beim Wiatn aum Hintaeingaung und hoffd aufn letztn Tropfn ausn Fassl!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Der Restltrinker hockt wieder beim Wirt am Hintereingang und hofft auf den letzten Tropfen aus’m Fass!', '[{"kategorie": "wörtlich", "text": "\"Der Resteschlürfer hockt wieder beim Wirt am Hintereingang und hofft auf den letzten Tropfen aus’m Fass!\"  2. Wie jeden Abend sitzt der Bierreste-Bettler beim Hintereingang und giert auf den Ausguss!  3. Am Hintereingang sitzt er – der arme Tropf, der auf den letzten Schluck aus dem Fass hofft!"}]'::jsonb, ''),
  ('vua-an-restltrinka-is-da-letzte-schluck-in-kan-glaasl-sicha', 'Vua an Restltrinka is da letzte Schluck in kan Glaasl sicha!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Vor einem Resteltrinker ist der letzte Schluck in keinem Glas sicher!', '[{"kategorie": "wörtlich", "text": "\"Wenn der Restetrinker kommt, hat auch der letzte Tropfen keine Überlebenschance!\"  2. Ein Resteltrinker fischt selbst im leeren Glas noch nach dem letzten Tropfen!  3. Kein Glas ist sicher, wenn der Restetrinker auftaucht!"}]'::jsonb, ''),
  ('ois-biafiara-kennda-an-jeedn-wiatn-in-wean', 'Ois Biafiara kennda an jeedn Wiatn in Wean!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Als Bierführer kennt er jeden Wirten in Wien!', '[{"kategorie": "wörtlich", "text": "\"Als Bierfahrer kennt er alle Gastwirte in Wien beim Namen!\"  2. Für ihn als Bierfahrer gibt es kein Wiener Gasthaus, das er nicht schon mal beliefert hat!  3. Er kennt jeden Wirt in Wien – schließlich bringt er ihnen das Bier!"}]'::jsonb, ''),
  ('beim-brai-hintn-hockd-scho-wiida-da-fassldippla-und-woat-dass-wos-tropfd', 'Beim Brai hintn hockd scho wiida da Fassldippla und woat, dass wos tropfd!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Beim Bräu hinten hockt schon wieder der Fassldippler und wartet, dass was tropft!', '[{"kategorie": "wörtlich", "text": "\"Hinten bei der Brauerei lungert schon wieder der Obdachlose und hofft auf den letzten Schluck!\"  2. Schon wieder sitzt der Sandler hinten beim Bräu und wartet, dass ihm wer das letzte Tropferl lässt!  3. Hinten beim Zapfhahn lungert schon wieder der Fassldippler und hofft auf den letzten Tropfen!"}]'::jsonb, ''),
  ('a-fassldippla-schliafds-letzte-restl-ausn-fassl', 'A Fassldippla schliafds letzte Restl ausn Fassl!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ein Fassltippler schlürft den letzten Rest aus dem Fass!', '[{"kategorie": "wörtlich", "text": "\"Ein Fasskipper schlürft den letzten Rest aus dem Fass!\"   2. Ein Fassltippler saugt die letzten Reste aus dem Fassboden"}, {"kategorie": "", "text": "Der Fassltippler ist das biologische Ende der Getränkekette!"}]'::jsonb, ''),
  ('so-a-biipn', 'So a Biipn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'So eine Pipen!', '[{"kategorie": "wörtlich", "text": "\"So ein Rotzlöffel!\"  2. Was für ein Flegel!  3. So ein Lümmel, echt frech!"}]'::jsonb, ''),
  ('mei-biipn-is-zwoa-ned-vagoided-dafia-owa-supa-in-schuss', 'Mei Biipn is zwoa ned vagoided, dafia owa supa in Schuss!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Meine Pipen ist zwar nicht vergoldet, dafür aber super in Schuss!', '[{"kategorie": "wörtlich", "text": "\"Meine Rohr ist zwar nicht vergoldet, dafür aber super in Schuss!\"  2. Mein Penis ist zwar nicht vergoldet, aber wenn’s drauf ankommt, liefert er Premiumservice!  3. Mein bestes Stück ist zwar nicht vergoldet – aber kerzengerade im Dienst! (siehe auich [[Biipn]])"}]'::jsonb, ''),
  ('i-woit-ia-telefonnumma-owa-si-hod-ma-de-biipn-geem', 'I woit ia Telefonnumma, owa si hod ma de Biipn geem!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich wollte ihre Telefonnummer, aber sie hat mir die Pipen gegeben!', '[{"kategorie": "wörtlich", "text": "\"Ich wollte ihre Telefonnummer, aber sie hat mich eiskalt abblitzen lassen!\"  2. Ich wollte ihre Nummer, aber sie hat mir eine eiskalte Abfuhr erteilt!  3. Ich hab nach ihrer Telefonnummer gefragt, aber sie hat mir eiskalt den Korb gegeben!"}]'::jsonb, 'wem de Biipn geem'),
  ('ea-woid-mi-auzindn-do-hob-i-eam-de-biipn-geem', 'Ea woid mi auzindn, do hob I eam de Biipn geem!', '', '', '', 'Wiener Gaunersprache', 'Er wollte mich anzünden, da habe ich ihm die Pipen gegeben!', '[{"kategorie": "wörtlich", "text": "\"Er wollte mich verpfeifen, da habe ich ihn ins Aus befördert!\"  2. Er wollte mich anschwärzen – da hab ich ihn eiskalt aussortiert!  3. Er hatte die Zunge locker – da hab ich ihm den Stecker gezogen!"}]'::jsonb, 'wem de Biipn geem'),
  ('gib-da-kraxn-de-biipn', 'Gib da Kraxn de Biipn!', '', '', '', 'Wiener Mechaniker-Slang', 'Gib der Kraxen die Pipen!', '[{"kategorie": "wörtlich", "text": "\"Gib der Klapperkiste Stoff!\""}, {"kategorie": "", "text": "Lass den Hobel röhren!  3. Gib dem Blechhaufen Feuer!  4. Bring das Schrottmobil zum Fliegen!  5. Drück drauf, was geht!  6. Gib Vollgas!"}]'::jsonb, ''),
  ('wem-de-biipn-geem', 'wem de Biipn geem', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem die Pipen geben', '[{"kategorie": "wörtlich", "text": "\"jemandem das Rohr geben\" (vom mittelhochdeutschen \"pippe\"=\"Röhre\")"}, {"kategorie": "fig.", "text": "jemandem eine Abfuhr erteilen, jemanden eiskalt abblitzen lassen, jemanden kalt auflaufen lassen, jemandem eiskalt den Korb geben, jemandem die [[Gurken]] geben"}, {"kategorie": "Gaunersprache", "text": "jemanden abservieren, absägen, eiskalt fallen lassen, ins Aus befördern, jemandem den Stecker ziehen"}]'::jsonb, 'I woit ia Telefonnumma, owa si hod ma de Biipn geem!'),
  ('ea-haengd-efta-aun-da-biabiipn-ois-aum-telefon', 'Ea hängd efta aun da Biabiipn ois aum Telefon!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Er hängt öfter an der Bierpipen als am Telefon!', '[{"kategorie": "wörtlich", "text": "\"Er hängt öfter am Bierzapfhahn als am Telefon!\"  2. Der Bierzapfhahn sieht ihn öfter als seine Mutter!  3. Er hängt am Zapfhahn wie ein Baby an der Milchflasche!"}]'::jsonb, ''),
  ('ea-haengd-aun-da-weibiipn-wiara-bauxal-aun-da-mueuechfloschn', 'Ea hängd aun da Weibiipn wiara Bauxal aun da Müüchfloschn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Er hängt an der Weinpipen wie ein Baby an der Milchflasche!', '[{"kategorie": "wörtlich", "text": "\"Er hängt am Weinrohr wie ein Baby an der Milchflasche!\"  2. Er nuckelt am Weinrohr wie andere am Strohhalm!  3. Der ist mit dem Weinrohr verwachsen – fast schon Rebe und Mensch in einem!"}]'::jsonb, ''),
  ('de-rotzbiipn-haett-friara-a-poa-waatschn-brauchd-daunn-waarad-viilleichd-wos-aus-eam-wuan', 'De Rotzbiipn hätt friara a poa Waatschn brauchd - daunn waarad viilleichd wos aus eam wuan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Diese Rotzpipen hätte früher ein paar Watschen gebraucht – dann wäre vielleicht was aus ihm geworden!', '[{"kategorie": "wörtlich", "text": "\"Dieser Flegel hätte früher ein paar Watschen gebraucht – dann wäre vielleicht was aus ihm geworden!\"  2. Diesem Lümmel hätte man früher ein paar gesunde Watschen mitgeben sollen, dann wär vielleicht ein brauchbarer Mensch aus ihm geworden!  3. Hätte man diesen respektlosen Bengel als Kind mit einer gehörigen Tracht Prügel eingedeckt, tät der heute nicht so rotzfrech daherreden!"}]'::jsonb, ''),
  ('im-biazoeoed-leanst-schnoella-wem-kenna-ois-auf-tinda', 'Im Biazööd leanst schnölla wem kenna ois auf Tinda!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Im Bierzelt lernst du schneller jemanden kennen als auf Tinder!', '[{"kategorie": "wörtlich", "text": "\"Im Bierzelt bist du schneller mit jemandem per Du als auf Tinder!\"  2. Im Bierzelt bekommst du schneller ’nen Kuss als online ein Like!  3. Tinder ist Kindergarten – im Bierzelt gibt’s Zungenkontakt ab Maß zwei!"}]'::jsonb, ''),
  ('noo-a-wuat-und-i-bian-da-ane-owa-sauwa', 'Noo a Wuat und I bian da ane - owa sauwa!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Noch ein Wort und ich birne dir eine - aber sauber!', '[{"kategorie": "wörtlich", "text": "\"Noch ein Wort, und ich verpasse dir einen Schlag auf den Kopf - aber so richtig!\"  2. Noch ein Mucks, und du kriegst was auf die Rübe – aber vom Feinsten!  3. Noch ein Pieps – und du kriegst eine Kopfnuss deluxe!"}]'::jsonb, ''),
  ('dea-woa-gestan-so-blau-dea-haedad-im-schdee-schlofn-kenna', 'Dea woa gestan so blau, dea hädad im Schdee schlofn kenna!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der war gestern so blau, der hätte im Stehen schlafen können!', '[{"kategorie": "wörtlich", "text": "\"Der war gestern so betrunken, der hätte im Stehen schlafen können!\"  2. Der war gestern dermaßen [[im]] Öl, dass er mit offenen Augen geschlafen hat!  3. Der war gestern dermaßen [[zu]], dass er im Stehen geschnarcht hat!"}]'::jsonb, ''),
  ('dea-is-zua-pruefung-gaungan-blaunk-wiara-weisses-blaadl-papia', 'Dea is zua Prüfung gaungan - blaunk wiara weisses Blaadl Papia!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der ist zur Prüfung gegangen blank wie ein weißes Blatt Papier!', '[{"kategorie": "wörtlich", "text": "\"Der ist völlig unvorbereitet zur Prüfung gegangen!\"  2. Der ist zur Prüfung gegangen, ohne auch nur die geringste Ahnung vom Prüfungsstoff zu haben!  3. Der war bei der Prüfung blank wie ein frisches Blatt Papier!"}]'::jsonb, ''),
  ('blaunk-wiara-weisses-blaadl-papia', 'blaunk wiara weisses Blaadl Papia', '', '', '', 'Wiener Sprüche, die sitzen!', 'blank wie ein weißes Blatt Papier', '[{"kategorie": "wörtlich", "text": "\"unbedarft wie ein weißes Blatt Papier\""}, {"kategorie": "", "text": "leer im Kopf wie eine gelöschte Festplatte"}, {"kategorie": "", "text": "ahnungslos, völlig unvorbereitet"}]'::jsonb, ''),
  ('i-woa-so-blaunk-i-haedad-kan-anzign-schdich-mochn-kenna', 'I woa so blaunk, I hädad kan anzign Schdich mochn kenna!', '', '', '', 'Wiener Kartentipplerjargon', 'Ich war so blank, ich hätte keinen einzigen Stich machen können!', '[{"kategorie": "wörtlich", "text": "\"Ich war so nackt auf der Hand, ich hätte keinen einzigen Stich machen können!\"  2. Ich hatte so wenig auf der Hand - da war kein Stich drin!\"  3. Ich war kartentechnisch nackt wie ein weißes Blattl Papier!"}]'::jsonb, ''),
  ('blaunk-gee', 'blaunk gee', '', '', '', 'Wiener Sprüche, die sitzen!', 'blank gehen', '[{"kategorie": "wörtlich", "text": "\"bei Kälte zu leicht bekleidet unterwegs sein\""}, {"kategorie": "", "text": "zu dünn angezogen sein\""}, {"kategorie": "", "text": "zu luftig unterwegs sein"}, {"kategorie": "", "text": "ohne ausreichenden Kälteschutz rausgehen"}]'::jsonb, 'Wea im Novemba bei Minusgraad blaunk geed, oone Mauntl und Kapuzn, is scho mutig - oda afoch nua blääd!'),
  ('wea-im-novemba-bei-minusgraad-blaunk-geed-oone-mauntl-und-kapuzn-is-scho-mutig-oda-afoch-nua-blaeaed', 'Wea im Novemba bei Minusgraad blaunk geed, oone Mauntl und Kapuzn, is scho mutig - oda afoch nua blääd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wer im November bei Minusgraden blank geht, ohne Mantel und Kapuze, ist schon mutig – oder einfach nur  dumm!', '[{"kategorie": "wörtlich", "text": "Im November bei Frosttemperaturen ohne Mantel oder Kapuze rauszugehen, ist schon sehr wagemutig - oder einfach nur dumm!  2. Im November ohne Winterkleidung in die Kälte zu gehen – das kann man kühn nennen oder schlicht unvernünftig!  3. Wer im November bei Minusgraden ohne Jacke rumrennt, muss entweder ein Eisbär sein oder ein kompletter Depp!"}]'::jsonb, 'blaunk gee'),
  ('ziagds-blaunk-buama', 'Ziagds blaunk, Buama!', '', '', '', 'Wiener Kartentipplerjargon', 'Zieht blank, Jungs!', '[{"kategorie": "wörtlich", "text": "\"Legt eure Karten offen, Jungs!\"  2. Legt die Karten offen auf den Tisch, Jungs!  3. Zeigt, was ihr in der Hand habt, Jungs!  4. Zeigt eure Hände!"}]'::jsonb, ''),
  ('de-ziagd-schnoella-blaunk-ois-d-haend-zsaummposchn-kaunnst', 'De ziagd schnölla blaunk ois d''Händ zsaummposchn kaunnst!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die zieht schneller blank, als du die Hände zusammenpaschen kannst!', '[{"kategorie": "wörtlich", "text": "\"Die zieht schneller blank, als du die Hände zusammenklatschen kannst!\"  2. Die ist schneller nackt, als du gucken kannst!  3. Die zeigt ihre Brüste schneller, als du dich umdrehen kannst!"}]'::jsonb, ''),
  ('dea-is-komplett-blaunk', 'Dea is komplett blaunk!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der ist komplett blank!', '[{"kategorie": "wörtlich", "text": "Der ist komplett abgebrannt!  2. Er hat überhaupt kein Geld mehr!  3. Der sitzt auf dem Trockenen - finanziell auf Null!  4. Der hat blankgezogen – im Portemonnaie!"}]'::jsonb, ''),
  ('eigee-wiara-bleamal-ohne-liachd', 'eigee wiara Bleamal ohne Liachd', '', '', '', 'Wiener Sprüche, die sitzen!', 'eingehen wie ein Blümchen ohne Licht', '[{"kategorie": "wörtlich", "text": "verkümmern wie eine Pflanze ohne Sonne"}, {"kategorie": "allg.", "text": "verwelken wie eine Blume ohne Tageslicht"}, {"kategorie": "", "text": "eingehen wie ein Pflänzchen im Dunkeln"}]'::jsonb, ''),
  ('si-is-no-imma-allaa-und-geed-ei-wiara-bleamal-oone-liachd', 'Si is no imma allaa - und geed ei wiara Bleamal oone Liachd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sie ist noch immer allein - und geht ein wie ein Blümchen ohne Licht!', '[{"kategorie": "wörtlich", "text": "\"Sie ist noch immer allein – und welkt dahin wie eine Blümchen ohne Licht!\"  2. In ihrer Einsamkeit verblasst sie – leise, wie ein Blümchen ohne Licht!  3. Ohne Liebe, ohne Nähe – sie vertrocknet innerlich wie eine Blume ohne Tageslicht!"}]'::jsonb, ''),
  ('aufn-kuchltisch-schdeed-a-bleamalvaasn-mid-an-vawoeoekdn-buschkawettl', 'Aufn Kuchltisch schdeed a Bleamalvaasn mid an vawöökdn Buschkawettl!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Auf dem Küchentisch steht eine Blümchenvase mit einem verwelkten Buschkawettl!', '[{"kategorie": "wörtlich", "text": "\"Auf dem Küchentisch steht eine Blumenvase mit einem verwelkten Blumenbouquet!\"  2. Auf dem Küchentisch steht eine Blumenvase mit einem verwelkten Blumenstrauß!  3. Auf dem Küchentisch steht eine Vase mit Blumen, die schon bessere Zeiten gesehen haben!"}]'::jsonb, ''),
  ('sei-tschapka-woa-poliad-da-blick-drunta-eiskoid', 'Sei Tschapka woa poliad, da Blick drunta eiskoid!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Sein Tschapka war poliert, der Blick darunter eiskalt!', '[{"kategorie": "wörtlich", "text": "\"Sein Kavalleriehelm war poliert, der Blick darunter eiskalt!\"  2. Sein Ulanenhelm glänzte wie Silber – doch sein Blick darunter war kalt wie Stahl!  3. Der Glanz des Helms täuschte – denn sein Blick war gnadenlos!"}]'::jsonb, ''),
  ('da-schuali-mit-da-blechhaubm', 'Da Schuali mit da Blechhaubm!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Der Schurli mit der Blechhaube!', '[{"kategorie": "wörtlich", "text": "\"Der Heilige Georg mit dem Blechhelm!\"  (nach dem heiligen Georg, dem Schutzpatron der Kreuzfahrer,  der immer in einer Rüstung mit Helm dargestellt wird und deswegen auch selbst die Bezeichnung \"Da Schuali mit da Blechhaubm\" trägt)"}, {"kategorie": "allg.", "text": "behelmter Mann, helmtragender Mann, \"Helmkopf\" , Wachmann, Polizist, Feuerwehrmann, \"Florianijünger\", \"Feuerwehrler\""}]'::jsonb, ''),
  ('schdee-ned-umadum-wia-da-schuali-mit-da-blechhaubm', 'Schdee ned umadum wia da Schuali mit da Blechhaubm!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Steh nicht herum wie der Schurli mit der Blechhaube!', '[{"kategorie": "wörtlich", "text": "\"Steh nicht so belämmert herum wie der Heilige Georg mit seinem Blechhelm!\"  2. Steh nicht so belämmert herum wie ein Wachmann mit Spitzhelm!  3. Du siehst so belämmert aus wie ein preißischer Soldat mit Pickelhaube!"}]'::jsonb, 'Da Schuali mit da Blechhaubm!'),
  ('dea-kriagd-fia-jedn-schaas-a-blechwimmal', 'Dea kriagd fia jedn Schaas a Blechwimmal!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der kriegt für jeden Schas ein Blechwimmerl!', '[{"kategorie": "wörtlich", "text": "\"Der kriegt für jeden Furz einen Orden!\"  2. Für jede Kleinigkeit verleiht man ihm einen Orden – wo sind wir denn?  3. Der braucht nur husten, und schon hängt man ihm einen Orden um den Hals!"}]'::jsonb, ''),
  ('seita-a-blechwimmal-auf-da-zungan-hod-schbuckda-wiara-laama', 'Seita a Blechwimmal auf da Zungan hod, schbuckda wiara Laama!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Seit er ein Blechwimmerl auf der Zunge hat, spuckt er wie ein Lama!', '[{"kategorie": "wörtlich", "text": "\"Seit er das Zungenpiercing hat, spuckt er wie ein Lama!\"  2. Mit dem Zungenpiercing trenzt er wie ein offener Wasserhahn!  3. Seit er das Zungenpiercing hat, kommt jedes Wort mit Spuckbegleitung!"}]'::jsonb, ''),
  ('gemma-aufd-bluatwiisn', 'Gemma aufd Bluatwiisn!', '', '', '', 'Wiener Gaunersprache', 'Gehen wir auf die Blutwiese!', '[{"kategorie": "wörtlich", "text": "\"Gehen wir raus auf den Blutacker!\"  2. (scherzhaft für): Klären wir das mit den Fäusten draußen auf der Wiese, bis das Blut fließt!  3. Lass uns das draußen wie echte Kerle regeln!  4. Komm raus auf die Blutwiese, dann zeig ich dir, was Sache ist!"}]'::jsonb, ''),
  ('vom-bocksheandlbaam-hod-laut-bibl-scho-johannes-da-teifa-gessn-drum-haassda-jo-aa-broodbaam', 'Vom Bocksheandlbaam hod laut Bibl scho Johannes da Teifa gessn - drum haassda jo aa Broodbaam!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Vom Bockshörndlbaum hat laut Bibel schon Johannes der Täufer gegessen - darum heißt er ja auch Brotbaum!', '[{"kategorie": "wörtlich", "text": "\"Schon  Johannes der Täufer soll laut Bibel am Karubenbaum geknabbert haben – deshalb nennt man ihn ja auch Brotbaum!\"  2. Johannes der Täufer soll sich in der Wüste von den Früchten des Karubenbaums ernährt haben – drum heißt er heute noch Brotbaum!  3. Der Name ''Brotbaum'' kommt nicht von ungefähr: schon Johannes der Täufer soll sich an seinen Früchten sattgegessen haben!"}]'::jsonb, ''),
  ('oone-bocksheandln-schmeckd-da-linsneintopf-nua-mea-hoib-so-guad', 'Oone Bocksheandln schmeckd da Linsneintopf nua mea hoib so guad!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ohne Bockshörndeln schmeckt der Linseneintopf nur mehr halb so gut!', '[{"kategorie": "wörtlich", "text": "\"Ohne Bockshornklee schmeckt der Linseneintopf nur noch halb so rund!\"  2. Ohne Bockshornklee fehlt dem Linseneintopf das gewisse Etwas!  3. Ohne das herbe, nussige Aroma des Bockshornklees bleibt der Linseneintopf geschmacklich auf halber Strecke stehen!"}]'::jsonb, ''),
  ('sei-argument-a-brachoida-und-de-diskussion-woa-beendet', 'Sei Argument? A Brachoida – und de Diskussion woa beendet!', '', '', '', 'Wiener Gaunersprache', 'Sein Argument? Ein Bracholder – und die Diskussion war beendet!', '[{"kategorie": "wörtlich", "text": "\"Sein Argument? Ein brachialer Faustschlag – und die Diskussion war beendet!\"  2. Sein Gegenargument? Ein gnadenloser Knüppelhieb – Diskussion beendet!  3. Sein Debattierstil? Ein primitiver Knochenbrecher - Diskussion beendet!"}]'::jsonb, ''),
  ('noch-dem-brachoida-host-de-waund-neich-schdreichn-kenna', 'Noch dem Brachoida host de Waund neich schdreichn kenna!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Nach diesem Bracholder hast du die Wand neu streichen können!', '[{"kategorie": "wörtlich", "text": "\"Nach diesem brachialen Hustenauswurf konnte man die Wand neu streichen!\"  2. Nach seinem Hustenausstoß hat sich der Schleim über die ganze Wand verteilt!  3. Einmal gehustet - und plötzlich sind hunderte Schleimbrocken an der Wand geklebt!"}]'::jsonb, ''),
  ('si-woa-so-blaadlwaach-dass-in-tiarlschdeeha-de-eia-massiad-hod', 'Si woa so blaadlwaach, dass in Tiarlschdeeha de Eia massiad hod!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Sie war so plattelweich, dass sie dem Türsteher die Eier massiert hat!', '[{"kategorie": "wörtlich", "text": "\"Sie war so sternhagelvoll, dass sie dem Türsteher zwischen die Beine gegriffen hat!\"  2. Sie war dermaßen angesoffen, dass sie dem Türsteher an die Hoden gegriffen hat!  3. Sie war dermaßen im Vollrausch, dass sie dem Türsteher dessen Weichteile massiert hat!"}]'::jsonb, ''),
  ('de-wundn-woa-so-brandich-dass-ausn-pflosta-aussegfunkd-hod', 'De Wundn woa so brandich, dass ausn Pflosta aussegfunkd hod!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Die Wunde war so brandig, dass es aus dem Pflaster rausgefunkt hat!', '[{"kategorie": "wörtlich", "text": "\"Die Wunde hat so sehr gebrannt, dass es aus dem Pflaster rausgefunkt hat!\"  2. Die Wunde hat so sehr gebrannt, dass das Pflaster kurz davor war, in Flammen aufzugehen!  3. Die Wunde war so heiß, dass sogar das Pflaster geraucht hat!"}]'::jsonb, ''),
  ('des-fleisch-woa-so-brandich-dass-si-sogoa-de-fliang-augschbiim-haettn', 'Des Fleisch woa so brandich, dass si sogoa de Fliang augschbiim hättn!', '', '', '', 'Wiener Fleischhauer-Slang', 'Das Fleisch war so brandig, dass sich sogar die Fliegen angespieben hätten!', '[{"kategorie": "wörtlich", "text": "\"Das Fleisch war so stichig, dass sich sogar die Fliegen übergeben hätten!\"  2. Das Fleisch hat so gestunken, dass selbst die Fliegen rückwärts geflogen sind!  3. Das Fleisch war so stichig, dass selbst die Fliegen gekotzt haben!"}]'::jsonb, ''),
  ('dea-wei-is-so-wos-von-brandich-a-echta-hecknklaescha', 'Dea Wei is so wos von brandich - a echta Hecknkläscha!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der Wein ist so was von brandig - ein echter Heckenklescher!', '[{"kategorie": "wörtlich", "text": "\"Der Wein ist so was von alkohollastig - ein echter Heckenklescher!\"  2. Der Wein brennt so was von die Kehle runter - ein echter Rachenputzer!  3. Dieser Wein brennt sich bis ins Hirn - ein echter Schädelspalter!"}]'::jsonb, ''),
  ('i-bin-so-brandich-i-kennts-gaunze-giasskaunl-aussaufn', 'I bin so brandich, I kennts gaunze Giasskaunl aussaufn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ich bin so brandig, ich könnte die ganze Gießkanne aussaufen!', '[{"kategorie": "wörtlich", "text": "\"Ich bin dermaßen vom Brand gezeichnet, dass ich die ganze Gießkanne austrinken könnte!\"  2. Ich hab so einen Brand, ich würd sogar das Blumenwasser ex trinken!  3. Ich hab so einen Brand, ich sauf den Gartenschlauch leer!"}]'::jsonb, ''),
  ('do-brandlds', 'Do brandlds!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Da brandelt es!', '[{"kategorie": "wörtlich", "text": "\"Da riecht’s verbrannt!\"  2. Hier riecht es nach Verbranntem!  3. Da schmurgelt irgendwas!"}]'::jsonb, ''),
  ('i-brandl-wiara-kaktus-im-hochoofn', 'I brandl wiara Kaktus im Hochoofn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ich brandle wie ein Kaktus im Hochofen!', '[{"kategorie": "wörtlich", "text": "\"Ich glühe vor Durst wie ein Kaktus im Hochofen!\"  2. Ich bin dehydriert wie ein Kaktus im Hochofen!  3. Ich bin vom Brand gezeichnet wie ein Kaktus im Hochofen!"}]'::jsonb, ''),
  ('ea-hod-so-laung-brandld-bis-eam-ane-in-de-goschn-ghaud-haum', 'Ea hod so laung brandld, bis eam ane in de Goschn ghaud haum!', '', '', '', 'Wiener Gaunersprache', 'Er hat so lange gebrandelt, bis sie ihm eine in die Goschen gehaut haben!', '[{"kategorie": "wörtlich", "text": "\"Er hat so lange gezündelt, bis sie ihm eine aufs Maul gehaut haben!\"  2. Er hat so lange provoziert, bis es gescheppert hat!  3. Er hat gestichelt, gespottet und gesudert, bis er eine aufs Maul gekriegt hat!"}]'::jsonb, ''),
  ('ia-oida-hockt-an-jeedn-toog-ab-siiwane-in-da-frua-beim-brandineesa', 'Ia Oida hockt an jeedn Toog ab siiwane in da Frua beim Brandineesa!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ihr Alter hockt jeden Tag ab sieben Uhr früh beim Brandineser!', '[{"kategorie": "wörtlich", "text": "\"Ihr Angetrauter sitzt jeden Tag ab sieben Uhr früh beim Branntweiner!\"  2. Ihr Alter steht um sieben Uhr auf, aber geht nicht ins Büro, sondern in die Branntweinschank!  3. Ihr Ehemann hat sein Büro im Branntweiner - offen ab 7 Uhr früh!"}]'::jsonb, ''),
  ('sei-woonsitzmoeoedung-hoda-jetzt-beim-brandinga', 'Sei Woonsitzmöödung hoda jetzt beim Brandinga!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Seine Wohnsitzmeldung hat er jetzt beim Brandinger!', '[{"kategorie": "wörtlich", "text": "\"Seine Wohnsitzmeldung hat er jetzt beim Branntweiner!\"  2. Der kann beim Brandinger jetzt bald seinen Meldezettel ausfüllen!  3. Er ist nicht obdachlos - er hat den Brandinger!"}]'::jsonb, ''),
  ('ea-is-ned-obdachlos-ea-hod-in-braundinoea', 'Ea is ned obdachlos - ea hod in Braundinöa!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Er ist nicht obdachlos - er hat den Brandineur!', '[{"kategorie": "wörtlich", "text": "\"Er ist nicht obdachlos - er hat den Branntweiner!\"  2. Er hat kein Zuhause - aber beim Branntweiner ist immer ein Platzl für ihn frei!  3. Er wohnt jetzt dort, wo andere nur trinken - beim Brandineur!"}]'::jsonb, ''),
  ('da-koarl-hod-im-braundweina-staummplotz-naumansschueued-und-hausrecht', 'Da Koarl hod im Braundweina Staummplotz, Naumansschüüd und Hausrecht!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Karl hat im Branntweiner Stammplatz, Namensschild und Hausrecht!', '[{"kategorie": "wörtlich", "text": "\"Der Karl ist Vollzeitgast beim Branntweiner!\"  2. Der Karl ist beim Branntweiner fix angestellt – als Dauertrinker!  3. Der Lebensmittelpunkt vom Karl ist flüssig - beim Branntweiner!"}]'::jsonb, ''),
  ('braundwein-wiakt-ned-ea-ealedigt', 'Braundwein wiakt ned - ea ealedigt!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Branntwein wirkt nicht - er erledigt!', '[{"kategorie": "wörtlich", "text": "\"Branntwein wirkt nicht - er vernichtet!\"  2. Branntwein wirkt nicht - er hat um!  3. Branntwein ist kein Medikament – er ist der letzte Dialog vorm Delirium!"}]'::jsonb, ''),
  ('a-schdampal-marueuengeist-und-de-leewa-salutiad', 'A Schdampal Marüüngeist - und de Leewa salutiad!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ein Stamperl Marillengeist - und die Leber salutiert!', '[{"kategorie": "wörtlich", "text": "\"Ein Stamperl Marillengeist – und die Leber steht stramm!\"  2. Ein Stamperl Marillengeist – und die Leber applaudiert!  3. Ein Stamperl Marillengeist – und meine Leber gibt Standing Ovations!"}]'::jsonb, ''),
  ('a-brasettl-is-magnetisch-es-ziagd-de-weiwa-au', 'A Brasettl is magnetisch - es ziagd de Weiwa au!', '', '', '', 'Wiener Gaunersprache', 'Ein Brasettel ist magnetisch - es zieht die Weiber an!', '[{"kategorie": "wörtlich", "text": "\"Goldenes Arm- oder Halsgeschmeide ist magentisch - es zieht die Frauen an!\"  2. Gold am Körper ist wie WLAN – Frauen verbinden sich automatisch!  3. Gold am Hals ist wie Katzenfutter für Frauen – sie kommen von allein!"}]'::jsonb, ''),
  ('des-gps-auf-mein-brasettl-piipst-efta-ois-mei-handy', 'Des GPS auf mein Brasettl piipst efta ois mei Handy!', '', '', '', 'Wiener Gaunersprache', 'Das GPS auf meinem Brasettel piepst öfter als mein Handy!', '[{"kategorie": "", "text": "\"Das GPS auf meiner Fußfessel piepst öfter als mein Handy!\"  2. Das GPS auf meiner Fußfessel piept öfter als mir meine Ex schreibt!  3. Die Fußfessel piepst so oft, ich fühl mich wie ein Tamagotchi unter Hausarrest!"}]'::jsonb, ''),
  ('i-kauf-meina-gschbusin-scheene-braslettn-und-sii-zoid-mas-im-bett-zruck', 'I kauf meina Gschbusin scheene Braslettn - und sii zoid mas im Bett zruck!', '', '', '', 'Wiener Gaunersprache', 'Ich kaufe meiner Gspusin schöne Brasletten - und sie zahlt es mir im Bett zurück!', '[{"kategorie": "wörtlich", "text": "\"Ich kaufe meiner Geliebten schöne Goldarmbänder - und sie zahlt es mir im Bett zurück!\"  2. Ich investiere in Goldschmuck – die Dividende kassier'' ich nachts im Bett!  3. Ich leg ihr Gold ans Handgelenk – sie legt Leidenschaft ins Schlafzimmer!"}]'::jsonb, ''),
  ('i-bin-ned-untataucht-i-hob-a-braslettn-aum-knechl', 'I bin ned untataucht - I hob a Braslettn aum Knechl!', '', '', '', 'Wiener Gaunersprache', 'Ich bin nicht untergetaucht - ich habe eine Brasletten am Knöchel!', '[{"kategorie": "wörtlich", "text": "\"Ich bin nicht untergetaucht - ich habe eine Fußfessel am Knöchel!\"  2. Ich bin nicht abgehauen – mein Knöchel hat jetzt bloß WLAN!  3. Ich bin nicht auf der Flucht, nur auf Empfang - Fußfessel am Knöchel!\""}]'::jsonb, ''),
  ('dea-hod-se-total-zuabetoniad', 'Dea hod se total zuabetoniad!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der hat sich total zubetoniert!', '[{"kategorie": "wörtlich", "text": "\"Der hat sich ins Nirwana gesoffen!\"   2. Der hat sich die Birne komplett weggekegelt!  3. Der hat sich selbst deinstalliert – mit Wodka!"}]'::jsonb, ''),
  ('de-brunzhittn-faeud-wia-de-hoelle-owa-si-is-a-oat-da-eroesung', 'De Brunzhittn fäud wia de Hölle - owa si is a Oat da Erösung!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Die Brunzhütte fäult wie die Hölle - aber sie ist ein Ort der Erösung!', '[{"kategorie": "wörtlich", "text": "\"Die Brunzhütte riecht wie die Hölle – aber sie ist ein Ort der Erlösung!\"  2. Der Pinkelpavillon stinkt wie ein Gulli auf Ecstasy – aber wer’s bis dahin schafft, wird erlöst!  3. Im Pissoir riecht''s, als wär der Teufel selbst drin gewesen – aber meine Blase nennt’s Heimat!"}]'::jsonb, ''),
  ('in-dera-brunzhittn-gibds-ois-aussa-saaf-liachd-und-zukunft', 'In dera Brunzhittn gibds ois - aussa Saaf, Liachd und Zukunft!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'In dieser Brunzhütte gibt es alles - außer Seife, Licht und Zukunft!', '[{"kategorie": "wörtlich", "text": "\"In diesem heruntergekommenen Sauflokal gibt es alles - außer Seife, Licht und Zukunft!\"  2. In dieser Kaschemme kriegst du alles – nur keine Hygiene, kein Licht und keine Hoffnung!  3. In dieser [[Bumsen]] gibt’s Schnaps, Geschichten und Schimmel – aber nix, was nach Zukunft riecht!\""}]'::jsonb, ''),
  ('brood-ma-uns-a-hendl', 'Brood ma uns a Hendl!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Braten wir uns ein Hendl!', '[{"kategorie": "wörtlich", "text": "\"Lass uns ein Hühnchen braten!\"  2. Wie wär’s mit Brathendl heute?  3. Zeit für Chicken aus’m Ofen!"}]'::jsonb, ''),
  ('dei-brooda-geed-noch-da-simmaringa-wossaleitung', 'Dei Brooda geed noch da Simmaringa Wossaleitung!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dein Brater geht nach der Simmeringer Wasserleitung!', '[{"kategorie": "wörtlich", "text": "\"Deine Uhr geht nach der Simmeringer Wasserleitung!\"   2. Deine Uhr geht komplett falsch!  3. Deine Taschenuhr zeigt ''ne völlig falsche Zeit an!  4. Deine Uhr spinnt total!"}]'::jsonb, ''),
  ('dei-uua-geed-noch-da-simmaringa-wossaleitung', 'Dei Uua geed noch da Simmaringa Wossaleitung!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Deine Uhr geht nach der Simmeringer Wasserleitung!', '[{"kategorie": "wörtlich", "text": "\"Deine Uhr geht komplett falsch!\"  2. Deine Uhr zeigt ''ne völlig falsche Zeit an!  3. Deine Uhr spinnt total!  4. [[Dei]] Brooda geed noch da Simmaringa Wossaleitung!"}]'::jsonb, ''),
  ('dei-uua-geed-noch-da-simmaringa-bassena', 'Dei Uua geed noch da Simmaringa Bassena!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Deine Uhr geht nach der Simmeringer Bassena!', '[{"kategorie": "", "text": "Deine Uhr geht komplett falsch!  2. Deine Uhr zeigt ''ne völlig falsche Zeit an!  3. Deine Uhr spinnt total!  4. Dei [[Brooda]] geed noch da Simmaringa Bassena!"}]'::jsonb, ''),
  ('i-bin-ned-kocht-und-a-ned-broodn', 'I bin ned kocht und a ned broodn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich bin nicht gekocht und auch nicht gebraten!', '[{"kategorie": "wörtlich", "text": "\"Ich lauf irgendwie nur auf halber Flamme!\"  2. Ich steh irgendwie nicht ganz im Saft!\"  3. Ich fühl mich wie altes Gemüse – nicht ganz frisch, nicht ganz schlecht!  4. Ich fühle mich nicht ganz wohl - irgendwie kränklich!  5. Ich bin nicht krank genug fürs Bett, aber auch nicht fit genug fürs Leben!"}]'::jsonb, ''),
  ('i-brauch-kan-terapeitn-i-brauch-a-gscheids-kawanaadl', 'I brauch kan Terapeitn - I brauch a gscheids Kawanaadl!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich brauche keinen Therapeuten – ich brauch'' ein gscheites Karbonadl!', '[{"kategorie": "wörtlich", "text": "\"Ich brauche keinen Therapeuten – ich brauch'' ein saftiges, auf Kohlenrost gebratenes Fleischstück!\"  2. Reden heilt nichts - ein gegrilltes Stück Fleisch schon!  3. Ein Fleischstück auf Kohlen hilft mehr als tausend Therapiesitzungen!"}]'::jsonb, ''),
  ('waunn-i-bsoffn-bin-reed-i-fliissend-englisch', 'Waunn I bsoffn bin, reed I fliißend Englisch!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wenn ich besoffen bin, rede ich fließend Englisch!', '[{"kategorie": "wörtlich", "text": "\"Wenn ich im Vollrausch bin, geht mir Englisch fließend über die Lippen!\"  2. Ab sechs [[Vierterln]] rede ich Englisch wie ein Muttersprachler!  3. Meine Englischkenntnisse wachsen proportional zum Alkoholspiegel!"}]'::jsonb, ''),
  ('bruadaschoft-saufn', 'Bruadaschoft saufn', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Bruderschaft saufen', '[{"kategorie": "wörtlich", "text": "\"Bruderschaft trinken\""}, {"kategorie": "", "text": "sich aufs brüderliche ''Du'' einsaufen"}, {"kategorie": "", "text": "mit jemandem eine Promillepartnerschaft eingehen"}]'::jsonb, 'Waunnsd Vareinsmitgliid wean wüüst, muasst easchd mit jedn Bruadaschoft saufn!'),
  ('waunnsd-vareinsmitgliid-wean-wueuest-muasst-easchd-mit-jedn-bruadaschoft-saufn', 'Waunnsd Vareinsmitgliid wean wüüst, muasst easchd mit jedn Bruadaschoft saufn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wenn du Vereinsmitglied werden willst, musst du erst mit jedem Bruderschaft saufen!', '[{"kategorie": "wörtlich", "text": "Mitglied im Verein wirst du erst, wenn du mit jedem mindestens einmal Bruderschaft getrunken hast!  2. Du willst rein in den Verein? Dann sauf zuerst Bruderschaft mit allen Mitgliedern!  3. Willst du im Verein dazugehören, musst du dich erstmal mit allen Mitgliedern vollbrüdern!"}]'::jsonb, ''),
  ('sii-haum-de-gaunze-nochd-duachpuudat', 'Sii haum de gaunze Nochd duachpuudat!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Sie haben die ganze Nacht durchgepudert!', '[{"kategorie": "wörtlich", "text": "\"Sie haben die ganze Nacht durchgebumst!\"  2. Sie haben die ganze Nacht durchgeschnackselt!  3. Sie haben die ganze Nacht durchgevögelt!  4. Die haben die ganze Nacht wie die Karnickel durchgerammelt!"}]'::jsonb, ''),
  ('sii-losst-si-von-eam-puudan', 'Sii losst si von eam puudan!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Sie lässt sich von ihm pudern!', '[{"kategorie": "wörtlich", "text": "\"Sie lässt sich von ihm bumsen!\"  2. Sie lässt sich von ihm vögeln!  3. Sie lässt sich von ihm schnackseln!"}]'::jsonb, ''),
  ('wia-de-security-kumman-ius-hods-a-puschkawueue-geem', 'Wia de Security kumman ius, hods a Puschkawüü geem!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wie die Security gekommen ist, hat es einen mordstrumm Puschkawül gegeben!', '[{"kategorie": "wörtlich", "text": "\"Als die Security kam, hat es einen Riesenwirbel gegeben!\"  2. Die Ankunft der Security löste einen heftigen Tumult aus!  3. Wie die Security da war, ist die Hölle losgebrochen!"}]'::jsonb, ''),
  ('waunn-dea-wos-in-d-haund-nimmt-kummt-da-aergste-puschkawueue-dabei-ausse', 'Waunn dea wos in d''Haund nimmt, kummt da ärgste Puschkawüü dabei ausse!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn er etwas in die Hand nimmt, kommt das ärgste Puschkawül dabei raus!', '[{"kategorie": "wörtlich", "text": "\"Wenn er etwas in die Hand nimmt, kommt das ärgste Chaos dabei raus!\"  2. Was immer er angreift, es endet im Chaos!  3. Was er anfasst, endet im Chaos!"}]'::jsonb, ''),
  ('da-bruella-von-mein-handal-dea-glitzad-jetzt-im-pfandal', 'Da Brülla von mein Handal dea glitzad jetzt im Pfandal!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Brüller von meinem Handerl, der glitzert jetzt im Pfanderl!', '[{"kategorie": "wörtlich", "text": "\"Der Brillantring von meinem Händchen, der glitzert jetzt in der Pfandleihanstalt!\"  (Textzeile aus Rainhard Fendrichs Song \"I bin a Negarant, Madam!)"}, {"kategorie": "", "text": "Mein Ring hat ein neues Zuhause – das [[Dorotheum]]!  3. Der Glitzer am Finger war gestern – heute funkelt er in der Vitrine von der [[Tante]] Dorli!"}]'::jsonb, ''),
  ('nochn-drittn-bruennaschdrassla-schbiast-nix-mea-weda-suang-no-dei-zungan', 'Nochn drittn Brünnaschdrassla schbiast nix mea - weda Suang no dei Zungan!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Nach dem dritten Brünnerstraßler spürst du nichts mehr - weder Sorgen noch deine Zunge!', '[{"kategorie": "wörtlich", "text": "\"Nach dem dritten Vierterl Brünnerstraßler Essigwasser spürst du nichts mehr - weder Sorgen noch deine Zunge!\"  2. Drei Gläser Brünnerstraßler – und du bist frei von Sorgen, Sprache und Geschmackssinn!  3. Wer drei Vierterln Brünnerstraßler schafft, hat keinen Gaumen mehr – aber dafür Ruhe im Kopf!"}]'::jsonb, ''),
  ('de-viicha-auf-da-weidn-lossn-in-sauaaumpfa-meistns-schdee-waeula-so-saua-schmeckd', 'De Viicha auf da Weidn lossn in Sauaaumpfa meistns schdee, wäula so saua schmeckd!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Die Viecher auf der Weide lassen den Sauerampfer meist stehen, weil er so sauer schmeckt!', '[{"kategorie": "wörtlich", "text": "\"Die Kühe auf der Weide lassen den Sauerampfer meistens stehen, weil er ihnen zu sauer ist!\"  2. \"Weidetiere meiden den Sauerampfer wegen seines sauren Geschmacks!\"  3. \"Der Sauerampfer, im Volksmund auch ''Sauerlump'' genannt, bleibt auf der Weide oft übrig, weil er sauer schmeckt und ihn die Kühe deshalb nicht mögen!\""}]'::jsonb, ''),
  ('den-sauaaumpfa-trinkst-ned-den-iwalebst', 'Den Sauaaumpfa trinkst ned, den iwalebst!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Diesen Sauerampfer trinkt man nicht, den überlebt man!', '[{"kategorie": "wörtlich", "text": "\"Dieses Säurewasser mit Weinetikett trinkt man nicht, das überlebt man!\"  2. Dieser Sauerampfer ist kein Wein, das ist eine Mutprobe im Glas!  3. Diesen Sauerampfer trinkt man, wenn man sich selbst nicht mehr mag!"}]'::jsonb, ''),
  ('dea-woa-so-buttawaach-den-haedast-auf-a-semmae-schmiian-kenna', 'Dea woa so buttawaach, den hädast auf a Semmä schmiian kenna!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der war so butterweich, den hättest du sogar auf eine Semmel schmieren können!', '[{"kategorie": "wörtlich", "text": "\"Der war so streichfähig, den hättest du sogar auf eine Semmel schmieren können!\"  2. Der war sternhagelvoll wie ein Wackelpudding!  3. Der war so butterweich, dass er in jede Backform gepasst hätte!"}]'::jsonb, ''),
  ('dea-woa-so-buttawaach-dea-haedad-sogoa-sei-eigane-muada-varrotn', 'Dea woa so buttawaach, dea hädad sogoa sei eigane Muada varrotn!', '', '', '', 'Wiener Gaunersprache', 'Der war so butterweich, der hätte sogar seine eigene Mutter verraten!', '[{"kategorie": "wörtlich", "text": "\"Der war so weichgeklopft, der hätte sogar seine eigene Mutter verraten!\"  2. Der war so mürbe, der hätte sogar seine eigene Mutter verraten!  3. Der war so weichgekocht - der hätte sogar Dinge gestanden, die er gar nicht getan hat!"}]'::jsonb, ''),
  ('dea-brood-scho-joare-bei-ia', 'Dea brood scho Joare bei ia!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der brät schon Jahre bei ihr!', '[{"kategorie": "wörtlich", "text": "\"Der baggert sie schon seit Ewigkeiten an!\"  2. Der wirbt schon seit Jahren um sie!  3. Der macht sich schon so lange an sie ran, der müsste fast Maut zahlen!"}]'::jsonb, ''),
  ('a-baeckagsoeoe-valiabd-si-ned-dea-geed-auf-wiara-geamtaag', 'A Bäckagsöö valiabd si ned - dea geed auf wiara Geamtaag!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Ein Bäckergeselle verliebt sich nicht - der geht auf wie ein Germteig!', '[{"kategorie": "wörtlich", "text": "\"Ein Bäckergeselle verliebt sich nicht - der geht auf wie ein Hefeteig!\"  2. Ein Bäckergeselle verliebt sich nicht – der öffnet sein Herz wie ein Germteig!  3. Ein Bäckergeselle wird nicht romantisch – höchstens locker-luftig!"}]'::jsonb, ''),
  ('fliag-mi-ned-au', 'Fliag mi ned au!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Fliege mich nicht an!', '[{"kategorie": "wörtlich", "text": "\"Geh mich nicht an!\"  2. Provoziere mich nicht!  3. Fordere mich nicht heraus!  4. Reize mich nicht!"}]'::jsonb, ''),
  ('neiadings-mochn-de-aubreendn-unsan-weana-maadln-lauta-schoko-butzaln', 'Neiadings mochn de Aubreendn unsan Weana Maadln lauta Schoko-Butzaln!', '', '', '', 'Wiener Gaunersprache', 'Neuerdings machen die Angebrannten unseren Wiener Mädchen lauter Schoko-Butzerln!', '[{"kategorie": "wörtlich", "text": "\"Neuerdings machen die Schwarzafrikaner unseren Wiener Mädels lauter Schoko-Babys!\"  2. Man sieht jetzt öfter Wiener Mädels mit afrikanischen Partnern und süßen Schoko-Babys!  3. Die Sonnenverbrannten machen unseren bleichen Wiener Mädels neuerdings lauter Schoko-Babys!"}]'::jsonb, ''),
  ('de-letztn-ziffan-von-meina-telefonnumma-san-drei-ochta', 'De letztn Ziffan von meina Telefonnumma san drei Ochta!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die letzten Ziffern meiner Telefonnummer sind drei Achter!', '[{"kategorie": "wörtlich", "text": "\"Meine Telefonnummer endet mit drei Achtern!\"  2. Am Ende meiner Telefonnummer stehen drei Achter!  3. Meine Telefonnummer endet dreimal mit der Ziffer 8!"}]'::jsonb, ''),
  ('des-vuadaraadl-hod-an-fettn-ochta-des-muass-dringend-zentriad-wean', 'Des Vuadaraadl hod an fettn Ochta - des muass dringend zentriad wean!', '', '', '', 'Wiener Mechaniker-Slang', 'Das Vorderrad hat einen fetten Achter – das muss dringend zentriert werden!', '[{"kategorie": "wörtlich", "text": "\"Das Vorderrad eiert total – da muss man unbedingt nachzentrieren!\"  2. Da ist ordentlich was verzogen – das Rad muss mal wieder in den Zentrierständer!  3. Das Rad wackelt wie ein Entenarsch – ab in die Werkstatt damit!  4. Das Laufrad hat einen massiven Seitenschlag – es muss neu eingespeicht bzw. zentriert werden!"}]'::jsonb, ''),
  ('leeg-dei-maschal-au', 'Leeg dei Maschal au!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Leg dein Mascherl an!', '[{"kategorie": "wörtlich", "text": "\"Binde dir deine Schleife um!\"  2. Schnür dir die Fliege unter''m Hemdskragen fest!  3. Zieh zum Hemd auch das Mascherl an!"}]'::jsonb, ''),
  ('um-wuevueue-ua-genau-leegds-schiffanaakl-au', 'Um wüvüü Ua genau leegds Schiffanaakl au?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Um wie viel Uhr genau legt das Schiffernakel an?', '[{"kategorie": "wörtlich", "text": "\"Um wie viel Uhr genau legt das Schiff an?\"  2. Wann genau kommt das Schiff im Hafen an?  3. Um wie viel Uhr genau läuft das Schiff ein?\""}]'::jsonb, ''),
  ('na-gee-leeg-endlich-in-schdaa-au', 'Na gee, leeg endlich in Schdaa au!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Na geh, leg endlich den Stein an!', '[{"kategorie": "wörtlich", "text": "\"Du bist dran! Leg endlich den Dominostein an!\"  2. Na los, spiel endlich deinen Stein!  3. Mach keinen auf Taktiker – leg den Dominostein endlich an!"}]'::jsonb, ''),
  ('ka-mensch-waass-wo-dea-gauna-sei-schwoazgoeoed-augleegd-hod', 'Ka Mensch waass, wo dea Gauna sei Schwoazgööd augleegd hod!', '', '', '', 'Wiener Gaunersprache', 'Kein Mensch weiß, wo der Gauner sein Schwarzgeld angelegt hat!', '[{"kategorie": "wörtlich", "text": "\"Keiner hat ''nen Schimmer, wo der Gauner seine Schwarzkohle geparkt hat!\"  2. Niemand weiß, wo der [[Strizzi]] sein nicht versteuertes Vermögen investiert hat!  3. Kein Schwein weiß, wo das Schlitzohr seine Schwarzknete veranlagt hat!"}]'::jsonb, ''),
  ('leeg-au-und-zueue', 'Leeg au und züü!', '', '', '', 'Wiener Gaunersprache', 'Leg an und ziel''!', '[{"kategorie": "wörtlich", "text": "\"Leg das Gewehr an und ziele!\"  2. Waffe hoch und anvisieren!  3. Setz an, halt das Ziel – und wart den richtigen Moment ab!"}]'::jsonb, ''),
  ('draa-nua-ned-au-mit-mia', 'Draa nua ned au mit mia!', '', '', '', 'Wiener Gaunersprache', 'Dreh nur nicht an mit mir!', '[{"kategorie": "wörtlich", "text": "\"Fordere mich ja nicht heraus!\"  2. Mach keine Welle, sonst kriegst du die Flut!  3. [[Leeg]] di nua ned au mit mia!"}]'::jsonb, ''),
  ('leeg-di-nua-ned-au-mit-mia', 'Leeg di nua ned au mit mia!', '', '', '', 'Wiener Gaunersprache', 'Leg dich nur nicht an mit mir !', '[{"kategorie": "wörtlich", "text": "\"Fordere mich ja nicht heraus!\"  2. Mach keine Welle, sonst kriegst du die Flut!  3. [[Draa]] nua ned au mit mia!"}]'::jsonb, ''),
  ('do-ghead-scho-vueue-chuzpe-dazu-dassd-da-neichn-kollegin-beim-easchdn-kaffee-ungfrogd-tipps-zua-figua-gibst', 'Do ghead scho vüü Chuzpe dazu, dassd da neichn Kollegin beim easchdn Kaffee ungfrogd Tipps zua Figua gibst!', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'Da gehört schon viel Chuzpe dazu, dass du der neuen Kollegin beim ersten Kaffee ungefragt Tipps zur Figur gibst!', '[{"kategorie": "wörtlich", "text": "Das ist schon eine gewaltige Frechheit, der neuen Kollegin direkt beim ersten Kaffee ungefragt Figur-Tipps zu geben!  2. Wie unverfroren muss man sein, der neuen Kollegin beim ersten Gespräch gleich ungefragt Kommentare zur Figur zu machen?  3. Das ist an Respektlosigkeit kaum zu überbieten – der neuen Kollegin direkt beim ersten Kaffee gleich ungefragt Figur-Tipps zu geben!"}]'::jsonb, ''),
  ('dea-hod-de-chuzpe-dassa-oone-einlodung-zua-hochzeit-von-seina-ex-geed-und-des-im-weissn-aunzug', 'Dea hod de Chuzpe, dassa oone Einlodung zua Hochzeit von seina Ex geed - und des im weissn Aunzug!', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'Der hat die Chuzpe, dass er ohne Einladung zur Hochzeit seiner Ex geht – und das im weißen Anzug!', '[{"kategorie": "wörtlich", "text": "\"Der besitzt die Dreistigkeit, ohne Einladung zur Hochzeit seiner Ex zu gehen - noch dazu im weißen Anzug!\"  2. Er hat tatsächlich den Mumm, ohne Einladung bei der Hochzeit seiner Ex aufzutauchen – und das im weißen Anzug!  3. Der hat doch tatsächlich den Nerv, ungeladen bei der Hochzeit seiner Ex aufzukreuzen - noch dazu im weißen Anzug!"}]'::jsonb, ''),
  ('des-woa-ka-brachoida-sondan-a-dochtl-fost-schoo-a-liibesbeweis', 'Des woa ka Brachoida, sondan a Dochtl - fost schoo a Liibesbeweis!', '', '', '', 'Wiener Gaunersprache', 'Das war kein Bracholder, sondern eine Tachtel – fast schon ein Liebesbeweis!', '[{"kategorie": "wörtlich", "text": "\"Das war kein brachialer Faustschlag, sondern eine Ohrfeige – fast schon ein Liebesbeweis!\"  2. Das war keine Trümmerwatschen – bestenfalls ein Flirt mit der flachen Hand!  3. Das war kein Bracholder, sondern bloß eine kleine Tachtel - wie ein Bussi mit dem Handrücken!"}]'::jsonb, ''),
  ('so-a-doik-schdoipad-duachd-woeoed-oone-dassa-begreifd-wosa-ois-aurichd', 'So a Doik schdoipad duachd Wööd, oone dassa begreifd, wosa ois aurichd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'So ein Tolk stolpert durch die Welt, ohne je zu begreifen, was er alles anrichtet!', '[{"kategorie": "wörtlich", "text": "\"So ein Tölpel stolpert durch die Welt, ohne je zu begreifen, was er alles anrichtet!\"  2. So ein Einfaltspinsel geistert durch die Weltgeschichte, ohne selbst mitzubekommen, was er alles anrichtet!  3. So ein Held der Ahnungslosigkeit stapft durch die Welt wie durch einen Porzellanladen! (soehe auch [[Doik]])"}]'::jsonb, ''),
  ('waunn-de-resi-doikn-mit-zwetschgnreesda-mochd-is-de-schdubn-scho-a-schdund-vuahea-grappaed-voi', 'Waunn de Resi Doikn mit Zwetschgnreesda mochd, is de Schdubn scho a Schdund vuahea grappäd voi!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Wenn die Resi Dalken mit Zwetschenröster macht, ist die Stube schon eine Stunde vorher gerappelt voll!', '[{"kategorie": "wörtlich", "text": "\"Wenn’s bei der Resi Dalken mit Zwetschkenröster gibt, bleibt kein Platz in der Stube leer!\"  2. Wenn die Resi Dalken mit Zwetschenröster macht, hockt die Nachbarschaft schneller da als die Feuerwehr beim Großbrand!  3. Bei Dalken mit Zwetschkenröster aus der Resi-Küche wird das Wohnzimmer zur Volksversammlung!"}]'::jsonb, ''),
  ('a-doikata-bleibd-a-doikata-aa-waunna-an-aunzug-auhod', 'A Doikata bleibd a Doikata, aa waunna an Aunzug auhod!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ein Dalkerter bleibt ein Dalkerter - auch wenn er einen Anzug anhat!', '[{"kategorie": "wörtlich", "text": "\"Ein Narr bleibt ein Narr - auch wenn er einen Anzug trägt!\"  2. Ein Dummkopf bleibt ein Dummkopf – auch im Maßanzug!  3. Ein Anzug macht aus einem [[Dillo]] noch keinen klugen Menschen!"}]'::jsonb, ''),
  ('so-doikad-wia-dea-si-auschdoeoed-is-des-chaos-scho-vuaprogrammiad', 'So doikad wia dea si auschdööd, is des Chaos scho vuaprogrammiad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'So dalkert, wie der sich anstellt, ist das Chaos schon vorprogrammiert!', '[{"kategorie": "wörtlich", "text": "\"So tollpatschig, wie der sich anstellt, ist das Chaos schon vorprogrammiert!\"  2. So unbeholfen wie der ist, läuft garantiert etwas schief!  3. So dümmlich, wie der agiert, ist das Unheil schon vorprogrammiert!"}]'::jsonb, ''),
  ('sei-ned-so-doikad', 'Sei ned so doikad!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Sei nicht so dalkert!', '[{"kategorie": "wörtlich", "text": "\"Sei nicht so ungeschickt!\"  2. Stell dich nicht so dämlich an!\"  3. Hör auf, dich so tollpatschig anzustellen!  4. Was soll das? Reiß dich zusammen!"}]'::jsonb, ''),
  ('dea-doikndiiwae-hods-echt-gschoffd-dassa-si-beim-soeoefi-soeoewa-ins-aug-schdichd', 'Dea Doikndiiwä hods echt gschoffd, dassa si beim Sööfi sööwa ins Aug schdichd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Dalkendübel hat es echt geschafft, dass er sich beim Selfie selber ins Auge sticht!', '[{"kategorie": "wörtlich", "text": "\"Die Doofbeule hat es echt geschafft, sich beim Selfie selbst ins Auge zu stechen!\"  2. Dieser Vollkoffer hat es doch tatsächlich geschafft, sich beim Selfie beinahe das Auge auszustechen!  3. Der Knallkopf hat’s geschafft, sich selbst frontal ins Auge zu pieken – mit dem Handy!"}]'::jsonb, ''),
  ('i-kaunn-afoch-ned-aundas-ois-dass-i-sei-doikarei-iagenwia-liab-find', 'I kaunn afoch ned aundas, ois dass I sei Doikarei iagenwia liab find!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich kann einfach nicht anders, als dass ich seine Dalkerei irgendwie lieb find!', '[{"kategorie": "wörtlich", "text": "\"Ich kann einfach nicht anders, als sein kindisches Gehabe irgendwie lieb zu finden!\"  2. Trotz seiner Faxenmacherei finde ich ihn irgendwie sympathisch!  3. So dämlich er sich auch verhält – ich muss ihn einfach gernhaben!"}]'::jsonb, ''),
  ('gestan-hod-ma-de-haeae-in-deckl-zwitschad', 'Gestan hod ma de Hää in Deckl zwitschad!', '', '', '', 'Wiener Gaunersprache', 'Gestern hat mir die Höh den Deckel gezwitschert!', '[{"kategorie": "wörtlich", "text": "\"Gestern hat mir die Polizei den Führerschein abgenommen!\"  2. Gestern hat mir die Polizei den Führerschein einkassiert!  3. Gestern haben mir die Herren in Blau meinen Schein konfisziert!  4. Gestan hod eam de Hee in [[Deckl]] ganiad!"}]'::jsonb, ''),
  ('hee-de-haeae', 'Hee, de Hää!', '', '', '', 'Wiener Gaunersprache', 'Hee, die Höh!', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"Achtung, Polizei!\" (Warnruf der Gauner vor der herannahenden Obrigkeit [[[Höh]]])"}, {"kategorie": "", "text": "\"Polente!\"  3. \"Kieberer im Anmarsch!\""}]'::jsonb, ''),
  ('wea-ma-in-bus-no-darenna', 'Wea ma in Bus no darenna?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Werden wir den Bus noch derrennen?', '[{"kategorie": "wörtlich", "text": "\"Werden wir den Bus noch erlaufen?\"  2. Werden wir den Bus noch erwischen?  3. Werden wir noch rechtzeitig bei der Busstation sein?"}]'::jsonb, ''),
  ('wem-wos-dazoeoen', 'wem wos dazöön', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem etwas derzählen', '[{"kategorie": "wörtlich", "text": "\"jemandem etwas erzählen\" (vom mittelhochdeutschen \"erzellen\"=\"erzählen\")"}, {"kategorie": "allg.", "text": "jemandem etwas berichten, schildern, mitteilen"}, {"kategorie": "fig.", "text": "jemandem die Meinung sagen, sich jemanden vorknöpfen, sich jemanden zur Brust nehmen"}]'::jsonb, ''),
  ('dem-wear-i-wos-dazoeoen', 'Dem wear I wos dazöön!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dem wird'' ich was erzählen!', '[{"kategorie": "fig.", "text": "\"Dem werde ich meine Meinung geigen!\"  2. Dem werde ich die Leviten lesen!  3. Mit dem werde ich Klartext reden!"}]'::jsonb, 'wem wos dazöön'),
  ('dazoeoe-ma-kaan-schaas', 'Dazöö ma kaan Schaas!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Derzähle mir keinen Schas!', '[{"kategorie": "wörtlich", "text": "\"Erzähle mir keinen Blödsinn!\"  2. Rede keinen Unsinn!  3. Rede keinen [[Holler]]!  4. Rede keinen [[Zwiefel]] daher!  5. [[Dazöö]] ma kaane Gschichdln!"}]'::jsonb, ''),
  ('schbueue-ma-a-runde-dariwuudl', 'Schbüü ma a Runde Dariwuudl?', '', '', '', 'Wiener Kartentipplerjargon', 'Spielen wir eine Runde Dariwudl?', '[{"kategorie": "wörtlich", "text": "\"Wer hat Lust auf eine Runde Dariwudel?\"  2. \"Wer hat Bock auf eine Runde Schenklklopfn und Schnaps? Dariwudl!\"  3. Lasst uns gemeinsam dariwudeln!"}]'::jsonb, ''),
  ('dea-dariwuudl-brauchd-ka-hindanis-dea-schdoipad-iwad-luft', 'Dea Dariwuudl brauchd ka Hindanis, dea schdoipad iwad Luft!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Dariwudel braucht kein Hindernis, der stolpert über die Luft!', '[{"kategorie": "scherzhaft für", "text": "\"Dieser Tollpatsch stolpert sogar über seinen eigenen Schatten!\"  2. Für diesen Tölpel ist sogar die Luft ein Stolperstein!  3. Dieser [[Hudriwudri]] stolpert schon, wenn er bloß ans Gehen denkt!"}]'::jsonb, ''),
  ('waunn-dea-zvueue-zwitschad-hod-dariwuudlda-umanaund-wiara-bsofanna-maikaeaefa', 'Waunn dea zvüü zwitschad hod, dariwuudlda umanaund wiara bsofanna Maikääfa!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wenn der zu viel gezwitschert hat, dariwuudelt er herum wie ein besoffener Maikäufer!', '[{"kategorie": "wörtlich", "text": "\"Wenn der zu viel getrunken hat, stolpert er durch die Gegend wie ein besoffener Maikäfer!\"  2. Wenn der einen zu viel intus hat, watschelt er durch die Gegend wie ein Pinguin auf Rollschuhen!  3. Wenn der zu viel gebechert hat, wuselt er herum wie ein aufgezogener Hamster!"}]'::jsonb, ''),
  ('tua-ma-no-a-runde-dariwuudln', 'Tua ma no a Runde dariwuudln?', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Tun wir noch eine Runde dariwudeln?', '[{"kategorie": "wörtlich", "text": "\"Spielen wir noch eine Runde Dariwudl?\"  2. \"Wer hat Bock auf noch eine Runde Schenklklopfn und Schnaps? Dariwudln!\"  3. Lasst uns gemeinsam noch eine Runde Dariwudel spielen!"}]'::jsonb, ''),
  ('wueuesd-an-koeoech', 'Wüüsd an Kööch?', '', '', '', 'Wiener Gaunersprache', 'Willst du einen Kölch?', '[{"kategorie": "wörtlich", "text": "\"Willst du Streit?\"  2. Suchst du Ärger?  3. Bist du auf eine Abreibung aus?  4. [[Wüüsd]] an Wickl?"}]'::jsonb, 'Wüüsd an Wickl?'),
  ('i-hob-heid-so-vueue-koeoech-gessn-dass-mei-oasch-jetzt-wiara-presslufthaumma-rattad', 'I hob heid so vüü Kööch gessn, dass mei Oasch jetzt wiara Presslufthaumma rattad!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich habe heute so viel Kohl gegessen, dass mein Arsch jetzt wie ein Presslufthammer rattert!', '[{"kategorie": "wörtlich", "text": "\"Ich hab heut so viel Kohl gefuttert, dass es mir jetzt einen Furz nach dem anderen hinten rausdrückt!\"  2. Ich hab heut so viel Kohl gegegessen, dass ich jetzt hinten Töne rausblas wie ''ne Tuba!  3. Ich hab heut so viel Kohl gefressen, dass mir jetzt ein Schas nach dem anderen aus dem Arsch entfleucht!"}]'::jsonb, ''),
  ('greesde-semmaekneedl-mid-an-koeoech', 'greesde Semmäkneedl mid an Kööch', '', '', '', 'Wiener Küche & Gaumenfreuden', 'geröstete Semmelknödel mit Kölch', '[{"kategorie": "wörtlich", "text": "\"Geröstete Semmelknödel mit Kohl\""}, {"kategorie": "Gastronomie", "text": "Knödelpfanne mit Kohl"}, {"kategorie": "", "text": "Knödel-Kohl-Pfanne"}]'::jsonb, 'Greesde Semmäkneedln mid an Kööch san des peafekte Restlessen: Kneedl im Pfandl aureesdn, Kööch dazua – featig!'),
  ('greesde-semmaekneedln-mid-an-koeoech-san-des-peafekte-restlessen-kneedl-im-pfandl-aureesdn-koeoech-dazua-featig', 'Greesde Semmäkneedln mid an Kööch san des peafekte Restlessen: Kneedl im Pfandl aureesdn, Kööch dazua – featig!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Geröstete Semmelknödel mit Kohl sind das perfekte Restlessen: Knödel in der Pfanne anrösten, Kohl dazu – fertig!', '[{"kategorie": "wörtlich", "text": "\"Pfannengeröstete Semmelknödel mit Kohl – ein bodenständiges Gericht, ideal zur Resteverwertung!\"  2. Knödelreste und etwas Kohl – kurz in die Pfanne, und schon steht ein herrliches Restlessen auf dem Tisch!\"  3. Für dieses einfache Restegericht werden gekochte Semmelknödel in Scheiben geschnitten, in Butter angeröstet und mit blanchiertem oder geschmortem Kohl angerichtet!"}]'::jsonb, 'greesde Semmäkneedl mid an Kööch'),
  ('an-oidn-koeoech-aufwaaman', 'an oidn Kööch aufwaaman', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen alten Kölch aufwärmen', '[{"kategorie": "wörtlich", "text": "\"alte Geschichten aufwärmen\""}, {"kategorie": "", "text": "alte Wunden aufreißen"}, {"kategorie": "", "text": "alte Geister heraufbeschwören"}, {"kategorie": "", "text": "Vergangenes wieder aufleben lassen"}]'::jsonb, ''),
  ('muassd-scho-wiida-den-oidn-koeoech-aufwaaman', 'Muassd scho wiida den oidn Kööch aufwaaman?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Musst du schon wieder den alten Kölch aufwärmen?', '[{"kategorie": "wörtlich", "text": "\"Musst du schon wieder diese alten Geschichten aufwärmen?\"  2. Musst du schon wieder dieses alte Streitthema wälzen?  3. Musst du schon wieder alte Leichen ausgraben?"}]'::jsonb, ''),
  ('mit-meina-oidn-hob-i-an-dauakoeoech', 'Mit meina Oidn hob I an Dauakööch!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mit meiner Alten habe ich einen Dauerkölch!', '[{"kategorie": "wörtlich", "text": "\"Mit meiner Ehefrau stehe ich im Dauerstreit!\"  2. Mit meiner Ehefrau streite ich Tag und Nacht!  3. Mit meiner besseren Hälfte liege ich im Dauerclinch!"}]'::jsonb, ''),
  ('damleschi-glaubs-auf', 'Damleschi, glaubs auf!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Tamleschi, klaub''s auf!', '[{"kategorie": "wörtlich", "text": "\"Tamleschi, klaube es auf!\" (Verballhornung des kroatischen \"Tamo leži!\"=\"Dort liegt es!\")"}, {"kategorie": "", "text": "Dort liegt es! Heb es auf! (typischer Spruch, wenn jemandem was aus der Hand rutscht)"}, {"kategorie": "", "text": "Liegt da! Aufheben!  4. Runtergefallen – aufheben!"}]'::jsonb, ''),
  ('den-brauchsd-ned-no-mea-deftn-dea-is-scho-deft-d-gmua', 'Den brauchsd ned no mea deftn - dea is scho deft''d gmua!', '', '', '', 'Wiener Gaunersprache', 'Den brauchst du nicht noch mehr zu deften - der ist schon gedeftet genug!', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"Den brauchst du nicht noch weiter fertigzumachen - der ist schon fertig genug!\"  2. \"Willst du ihn komplett in Grund und Boden stampfen? Der ist doch eh schon am Ende!\"  3. Du musst nicht weiter auf ihn eindreschen – der liegt eh schon am Boden!"}]'::jsonb, ''),
  ('deft-d', 'deft''d', '', '', '', 'Wiener Gaunersprache', 'gedeftet', '[{"kategorie": "wörtlich", "text": "\"niedergedrückt\" (vom niederdeutschen \"deften\"=\"in Grund und Boden stampfen\")"}, {"kategorie": "allg., Gaunerjargon", "text": "niedergeschlagen, erledigt, entmutigt, \"geschlaucht\", \"groggy\""}]'::jsonb, ''),
  ('so-defted-wia-heit-woari-scho-laung-nimma', 'So defted wia heit woari scho laung nimma!', '', '', '', 'Wiener Gaunersprache', 'So gedeftet wie heute war ich schon lang nimmer!', '[{"kategorie": "", "text": "So erledigt wie heute war ich schon lange nicht mehr!  2. So geschlaucht wie heute war ich schon lange nicht mehr!  3. So groggy wie heute war ich schon lange nicht mehr!"}]'::jsonb, 'Den brauchsd ned no mea deftn - dea is scho deft''d gmua!'),
  ('heast-dearischa-host-deine-uawaschln-im-oasch-parkd', 'Heast Dearischa, host deine Uawaschln im Oasch parkd?', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Hey, Derischer, hast du deine Ohrwascheln im Arsch geparkt?', '[{"kategorie": "wörtlich", "text": "\"Hey, du Schwerhöriger, hast du deine Ohren im Arsch geparkt?\"  2. Hey, du Hörbehinderter, hast du deine Ohren auf Durchzug gestellt?  3. Hey, du [[derische]] Kapelle, ich rede mit dir!"}]'::jsonb, ''),
  ('waunnsd-wos-von-dem-wueuesd-daunn-reedst-wia-zu-an-dearischn', 'Waunnsd wos von dem wüüsd, daunn reedst wia zu an Dearischn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Willst du was von ihm, dann redest du wie zu einem Derischen!', '[{"kategorie": "wörtlich", "text": "\"Willst du was von ihm, dann redest du wie zu einem Schwerhörigen!\"  2. Bei ihm musst du jedes Wort dreimal sagen, sonst kommt’s nicht an!  3. Wenn jemand etwas von ihm will, dann stellt er sich einfach taub!"}]'::jsonb, ''),
  ('si-dearisch-schdoeoen', 'si dearisch schdöön', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich derisch stellen', '[{"kategorie": "wörtlich", "text": "\"sich taub stellen\""}, {"kategorie": "", "text": "seine Ohren auf Durchzug schalten"}, {"kategorie": "", "text": "so tun, als wäre man taub"}, {"kategorie": "", "text": "\"einen auf taube Nuss machen\""}]'::jsonb, 'Waunn I puudan wüü, schdööd si mei Oide imma dearisch!'),
  ('waunn-i-puudan-wueue-schdoeoed-si-mei-oide-imma-dearisch', 'Waunn I puudan wüü, schdööd si mei Oide imma dearisch!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Wenn ich pudern will, stellt sich meine Alte immer derisch!', '[{"kategorie": "wörtlich", "text": "\"Wenn ich Sex will, stellt sich meine Alte immer taub!\"  2. Sobald ich ranwill, spielt meine Alte die Unschuld vom Lande – und hört auf einmal nichts mehr!  3. Red ich von Sex, macht sie einen auf taube Nuss!"}]'::jsonb, 'si dearisch schdöön'),
  ('in-da-klaanan-kapoeoen-aum-woidraund-brennd-jedn-toog-a-keazal-und-daneem-liing-imma-frische-bluman', 'In da klaanan Kapöön aum Woidraund brennd jedn Toog a Keazal, und daneem liing imma frische Bluman!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'In der kleinen Kapelle am Waldrand brennt jeden Tag ein Kerzerl und daneben liegen immer frische Blumen!', '[{"kategorie": "wörtlich", "text": "\"In der Andachtsstätte am Waldrand steht immer eine brennende Kerze, umgeben von frischen Blumen!\"  2. Am Waldrand wacht die kleine Kapelle – darin ein Licht, das nie verlischt, umrahmt von stillen Blüten des Trostes!  3. Da draußen bei der kleinen Kapelle am Waldrand leuchtet jeden Tag eine Kerze – immer mit frischen Blumen daneben!"}]'::jsonb, ''),
  ('a-dearische-kapoeoen', 'a dearische Kapöön', '', '', '', 'Wiener Sprüche, die sitzen!', 'eine törische Kapelle', '[{"kategorie": "wörtlich", "text": "\"eine schwerhörige Musikkapelle\""}, {"kategorie": "scherzhaft für", "text": "Schwerhöriger, \"taube Nuss\" (jemand, der etwas überhört hat, was ihm gegolten hätte)"}, {"kategorie": "fig., scherzhaft für", "text": "\"Weghörer\" (jemand, der so tut, als würde er die an ihn gerichteten Worte nicht hören), \"Ignorant\" , Sturkopf, Querulant, \"Weghörer\""}]'::jsonb, ''),
  ('heast-du-dearische-kapoeoen-schdoeoe-de-lauscha-auf', 'Heast, du dearische Kapöön, schdöö de Lauscha auf!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Hey, du törische Kapelle, stell die Lauscher auf!', '[{"kategorie": "wörtlich", "text": "\"Hey, du taube Nuss, spitz mal die Lauscher!\"  2. Hallo, du taube Nuss, hör endlich zu, es geht um dich!  3. Hey, du Schwerhöriger, stell mal die Antennen auf!"}]'::jsonb, 'a dearische Kapöön'),
  ('huach-zua-du-dearische-kapoeoen-und-tua-ned-so-ois-waarad-i-luft', 'Huach zua, du dearische Kapöön, und tua ned so, ois waarad I Luft!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Horch zu, du törische Kapelle, und tu nicht so, als wäre ich Luft!', '[{"kategorie": "wörtlich", "text": "\"Hör zu, du taube Nuss, und tu nicht so, als wäre ich Luft!\"  2. Mach mal die Ohren auf, du Ignorant auf zwei Beinen, und tu nicht so, als wäre ich Luft!  3. Tu nicht so, als wär ich Luft – ich red mit dir und nicht mit der Wand!"}]'::jsonb, 'a dearische Kapöön'),
  ('i-bin-mit-dein-vuaschlog-komplett-dakoa', 'I bin mit dein Vuaschlog komplett dakoa!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Ich bin mit deinem Vorschlag komplett d''accord!', '[{"kategorie": "wörtlich", "text": "\"Ich stimme deinem Vorschlag voll und ganz zu!\"  2. Ich habe nichts an deinem Vorschlag auszusetzen!  3. Was deinen Vorschlag betrifft, bin ich total auf deiner Wellenlänge!"}]'::jsonb, ''),
  ('des-weama-scho-irgendwii-deixln', 'Des weama scho irgendwii deixln!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das werden wir schon irgendwie deichseln!', '[{"kategorie": "wörtlich", "text": "\"Das werden wir schon irgendwie schaffen!\"  2. Das kriegen wir schon irgendwie hin!  3. Das werden wir schon irgendwie [[schupfen]]!"}]'::jsonb, ''),
  ('kan-deka-hian-haum', 'kan Deka Hian haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'keinen Deka Hirn haben', '[{"kategorie": "wörtlich", "text": "\"kein Gramm Hirn im Schädel haben\""}, {"kategorie": "", "text": "\"völlig intelligenzbefreit sein\""}, {"kategorie": "", "text": "nur Luft im Hirn haben (Synonyme für [[Oida, dea hod kan Deka Hian, owa glaubd, ea is da Einstein!]])"}]'::jsonb, ''),
  ('oida-dea-hod-kan-deka-hian-owa-glaubd-ea-is-da-einstein', 'Oida, dea hod kan Deka Hian, owa glaubd, ea is da Einstein!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Alter, der hat keinen Deka Hirn, aber glaubt, er ist der Einstein!', '[{"kategorie": "wörtlich", "text": "\"Mensch, der hat kein Deka Hirn, hält sich selbst aber für Einstein!\"  2. Junge, der hat kein Deka Hirn, aber glaubt, er ist der Einstein vom Dienst!  3. Der hat null Deka Hirn, dafür aber ein Ego wie Einstein!"}]'::jsonb, 'kan Deka Hian haum'),
  ('bist-deppad', 'Bist deppad?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Bist deppert?', '[{"kategorie": "wörtlich", "text": "\"Bist du blöd?\"  2. Hör mal, was soll das?  3.Spinnst du?  4. Sag mal, geht’s noch?  5. [[Hast]] du einen Pecker?"}]'::jsonb, ''),
  ('des-is-a-deppade-gschichd', 'Des is a deppade Gschichd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das ist eine tepperte Geschichte!', '[{"kategorie": "wörtlich", "text": "\"Das ist eine blöde Geschichte!\" 2. Das ist eine unangenehme Sache!  3. Das ist eine verzwickte Angelegenheit!"}]'::jsonb, ''),
  ('fia-di-woari-ollawaeu-sowiiso-nua-a-deppada-bua', 'Fia di woari ollawäu sowiiso nua a deppada Bua!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Für dich war ich alleweil sowieso nur ein depperter Bub!', '[{"kategorie": "wörtlich, Songtext von Horst Chmela", "text": "\"Für dich war ich sowieso immer nur ein dummer Bub!\"  2. In deinen Augen war ich sowieso immer nur ein blöder Junge!  3. Du hast mich doch sowieso nie wirklich ernst genommen!"}]'::jsonb, ''),
  ('wos-fiara-deppade-froog', 'Wos fiara deppade Froog!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Was für eine depperte Frage!', '[{"kategorie": "wörtlich", "text": "\"Was für eine blöde Frage!\"  2. Was für eine dumme Frage!  3. Wie albern ist das denn?  4. Das ist doch eine völlig sinnlose Frage!"}]'::jsonb, ''),
  ('wem-deppad-kumma', 'wem deppad kumma', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem deppert kommen', '[{"kategorie": "wörtlich", "text": "\"jemandem blöd kommen\""}, {"kategorie": "", "text": "jemandem auf die blöde Tour kommen"}, {"kategorie": "", "text": "jemandem gegenüber unverschämt werden\""}]'::jsonb, ''),
  ('ned-kumma-deppad', 'Ned kumma deppad!', '', '', '', 'Wiener Gaunersprache', 'Komm mir nur ja nicht deppert!', '[{"kategorie": "wörtlich", "text": "\"Komm mir nur ja nicht blöd!\"  2. Komm mir nur ja nicht auf die blöde Tour!  3. Spar dir deine dämliche Nummer!  4. Komm mir nur ja nicht frech!"}]'::jsonb, ''),
  ('waunnsd-ma-deppad-kummsd-daunn-knoids', 'Waunnsd ma deppad kummsd, daunn knoids!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn du mir deppert kommst, dann knallt''s!', '[{"kategorie": "wörtlich", "text": "\"Wenn du mir blöd kommst, dann knallt''s!\"  2. Wenn du mir auf die blöde Tour kommst, setzt’s was!  3. Komm mir nicht so blöd, sonst fliegt dir gleich was um die Ohren!"}]'::jsonb, 'wem deppad kumma'),
  ('deppad-sei-kaunnst-dahaam', 'Deppad sei kaunnst dahaam!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Deppert sein kannst du daheim!', '[{"kategorie": "wörtlich", "text": "\"Blöd aufführen kannst du dich zu Hause!\"  2. Zum Blödsein bleib lieber zu Hause!  3. So einen Auftritt kannst du daheim abziehen – aber nicht hier!"}]'::jsonb, ''),
  ('i-gfrei-mi-wia-deppad', 'I gfrei mi wia deppad!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich freue mich wie deppert!', '[{"kategorie": "wörtlich", "text": "\"Ich freue mich wie verrückt!\"  2. Ich bin total aus dem Häuschen!  3. Ich freie mich riesig! Ich bin [[narrisch]] froh!"}]'::jsonb, ''),
  ('wo-is-mei-deppads-haendi', 'Wo is mei deppads Händi?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Wo ist mein teppertes Handy?', '[{"kategorie": "wörtlich", "text": "\"Wo ist mein blödes Handy?\"  2. Wo ist mein verdammtes Telefon?  3. Wo ist mein verfluchtes Mobiltelefon bloß hingekommen?"}]'::jsonb, ''),
  ('dea-is-da-depp-fia-olle', 'Dea is da Depp fia olle!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Der ist der Depp für alle!', '[{"kategorie": "wörtlich", "text": "\"Er ist für alle der Depp vom Dienst!\"  2. Der lässt alles mit sich machen!  3. Er ist der Prügelknabe für alle!  4. Er ist der Trottel vom Dienst!"}]'::jsonb, ''),
  ('du-depp-du-deppada', 'Du Depp, du deppada!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du Depp, du depperter!', '[{"kategorie": "wörtlich", "text": "\"Du Trottel, du depperter!\"  2. \"Du Hornochse, du blöder\"!  3. \"Du Vollidiot vom Dienst!\"  3."}]'::jsonb, ''),
  ('an-deppn-owareissn', 'an Deppn owareissn', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Teppen herunterreißen', '[{"kategorie": "wörtlich", "text": "\"sich zum Deppen machen\", \"sich zum Affen machen\", \"herumkaspern\", \"den Kasperl spielen\", \"den Clown spielen\""}, {"kategorie": "", "text": "den Dummen spielen, sich dummstellen, sich unwissend geben, den Ahnungslosen mimen, sich ahnungslos stellen"}]'::jsonb, ''),
  ('warum-soi-i-vua-da-gaunzn-klass-an-deppn-owareissn', 'Warum soi I vua da gaunzn Klass an Deppn owareissn?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Warum soll ich vor der ganzen Klasse einen Deppen runterreißen?', '[{"kategorie": "wörtlich", "text": "\"Warum soll ich mich vor der ganzen Klasse zum Deppen machen?\"  2. Warum soll ich vor der ganzen Klasse den [[Kasperl]] spielen?  3. Warum soll ich mich vor der ganzen Klasse zum Affen machen?"}]'::jsonb, 'an Deppn owareissn'),
  ('du-kaunnst-ned-jedes-moi-an-deppn-owareissn-waunns-eanst-wiad', 'Du kaunnst ned jedes Moi an Deppn owareissn, waunns eanst wiad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Du kannst nicht jedes Mal einen Deppen runterreißen, wenn’s ernst wird!', '[{"kategorie": "wörtlich", "text": "\"Du kannst nicht jedes Mal den Deppen spielen, wenn''s ernst wird!\"  2. Du kannst dich nicht jedes Mal dummstellen, wenn es brenzlig wird!  3. Du kannst nicht jedes Mal den Ahnungslosen mimen, wenn es ernst wird!"}]'::jsonb, 'an Deppn owareissn'),
  ('du-bist-scho-a-gaunza-depp', 'Du bist scho a gaunza Depp!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Du bist schon ein ganzer Depp!', '[{"kategorie": "wörtlich", "text": "\"Du bist wirklich durch und durch ein Tepp!\"  2. Du bist mir schon ein richtiger Hornochse!  3. Du bist wirklich ein Idiot, weißt du das?"}]'::jsonb, ''),
  ('i-loss-mi-do-ned-zum-deppn-mochn', 'I loss mi do ned zum Deppn mochn!', '', '', '', '', 'Ich lasse mich doch nicht zum Teppen machen!', '[{"kategorie": "", "text": "Ich lass mich doch nicht für blöd verkaufen!  2. Ich lass mich doch nicht zum Idioten abstempeln!"}]'::jsonb, ''),
  ('wem-aum-laam-gee', 'wem aum Laam gee', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem auf den Leim gehen', '[{"kategorie": "wörtlich", "text": "\"auf jemandes Trick hereinfallen\" (aus der Jägersprache, wo Leimruten, also Äste, mit einer klebrigen Substanz (Leim) beschmiert wurden, um Vögel zu fangen)"}, {"kategorie": "", "text": "sich von jemandem wie ein Anfänger reinlegen lassen"}, {"kategorie": "", "text": "sich von jemandem über den Tisch ziehen lassen"}]'::jsonb, ''),
  ('i-bin-eam-voi-aum-laam-gaungan', 'I bin eam voi aum Laam gaungan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich bin ihm voll auf den Leim gegangen!', '[{"kategorie": "wörtlich", "text": "\"Ich bin voll auf ihn reingefallen!\"  2. Ich habe mich voll von ihm täuschen lassen!  3. Er hat mich komplett über den Tisch gezogen!"}]'::jsonb, 'wem aum Laam gee'),
  ('scho-in-da-schui-woara-a-deppal', 'Scho in da Schui woara a Deppal!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Schon in der Schule war er ein Depperl!', '[{"kategorie": "wörtlich", "text": "\"Schon in der Schule war er ein Tepperl!\"  2. Schon als Schüler war er ein ziemlicher Trottel!  3. Schon in der Schule war er ein ziemlicher [[Hirnschüssler]]!  4. Schon in jungen Jahren war er ein wenig begriffsstutzig"}]'::jsonb, '')
